			pcall(function() part.CanCollide = original end)
			collisions[part] = nil; collisionCount = math.max(0, collisionCount - 1)
		end
		collisionParts[part] = nil; state.collisionParts = collisionCount
	end
	local function rebuildCollisionParts(model)
		table.clear(collisionParts)
		if model then for _, part in ipairs(model:GetDescendants()) do trackCollisionPart(part) end end
	end
	local function cancelMove(keepCollision)
		local previous = movement or hover
		movement, hover = nil, nil
		if previous then
			if previous.completed then previous.completed:Disconnect() end
			if previous.tween then
				local ok, err = pcall(function() previous.tween:Cancel() end)
				if not ok then state.lastError = tostring(err) end
			end
			if previous.driver then previous.driver:Destroy() end
		end
		-- Replacement legs share the original snapshot: never briefly turn
		-- collisions back on while still crossing furniture/walls.
		if not keepCollision then
			for part, original in pairs(collisions) do
				local ok, err = pcall(function() part.CanCollide = original end)
				if not ok then state.lastError = tostring(err) end
			end
			table.clear(collisions); collisionCount, state.collisionParts = 0, 0
		end
		state.moving, state.holdingPosition, nextMove = false, false, 0
	end
	local function noCollision()
		if not (movement or hover) or not character then return end
		for part in pairs(collisionParts) do
			if part.Parent == nil then
				untrackCollisionPart(part)
			else
				if collisions[part] == nil then collisions[part] = part.CanCollide; collisionCount += 1 end
				if part.CanCollide then part.CanCollide = false end
			end
		end
		state.collisionParts = collisionCount
	end
	local function gameInput()
		if game.PlaceVersion ~= 7510 then return end
		local remotes = character and character:FindFirstChild("Remotes")
		local remote = remotes and remotes:FindFirstChild("KeyEvent")
		return remote and remote:IsA("RemoteEvent") and remote or nil
	end
	local function inputFrame(frame, position, point)
		-- Directional skills start at the character, not the orbit camera.
		-- At close range/Above/Down these rays can point in opposite directions.
		-- Keep the payload camera origin, but align its rotation with root->aim.
		local direction = point - position
		if direction.Magnitude < 0.001 then return frame end
		local up = math.abs(direction.Unit:Dot(Vector3.yAxis)) > 0.98 and Vector3.zAxis or Vector3.yAxis
		return CFrame.lookAt(frame.Position, frame.Position + direction, up)
	end
	local function inputPayload(code, aim, untracked)
		local remote = gameInput()
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local camera = Workspace.CurrentCamera
		if not remote or not root or not camera then return end
		local point = aim or root.Position + root.CFrame.LookVector * 10
		local frame = inputFrame(camera.CFrame, root.Position, point)
		local tracked = not untracked and activeFarm() and (code == 0x01 or code == 0x45 or code == 0x52 or code == 0x46 or code == 0x43) and target or nil
		return { remote = remote, name = inputNames[code], hit = CFrame.new(point), camera = frame, position = root.Position,
			character = character, characterRoot = root, target = tracked, targetParent = tracked and tracked.Parent,
			bossRoot = tracked and tracked:FindFirstChild("HumanoidRootPart") }
	end
	local function send(payload, direction)
		-- Up can trigger a released/charged skill: do not aim at its stale Down point.
		local bossRoot, model = payload.bossRoot, payload.target
		local hum = model and model:FindFirstChildOfClass("Humanoid")
		if bossRoot and model.Parent == payload.targetParent and model:FindFirstChild("HumanoidRootPart") == bossRoot
			and hum and hum.Health > 0 and hum.Health < math.huge and payload.character == character then
			payload.hit = CFrame.new(bossRoot.Position)
			payload.position = payload.characterRoot.Position
			payload.camera = inputFrame(payload.camera, payload.position, bossRoot.Position)
		end
		if direction == "Down" and (payload.name == "E" or payload.name == "R" or payload.name == "F" or payload.name == "C") then
			local delta = payload.hit.Position - payload.position
			state.lastSkillAimDot = delta.Magnitude > 0.001 and payload.camera.LookVector:Dot(delta.Unit) or nil
		end
		payload.remote:FireServer(inputToken, payload.name, direction, payload.hit, nil, payload.camera, payload.position, nil)
	end
	local function flushNativeReleases()
		if not isrbxactive() then return end
		for code in pairs(nativeReleases) do
			local ok, err = pcall(keyrelease, code)
			if ok then nativeReleases[code] = nil else state.lastError = tostring(err) end
		end
	end
	local function releaseKey()
		if not held then return end
		local code = held
		held = nil
		local payload = heldRemote
		local gameRelease = heldGameRelease
		heldRemote, heldGameRelease = nil, nil
		local ok, err = pcall(function()
			if payload then send(payload, "Up")
			elseif isrbxactive() then
				keyrelease(code); nativeReleases[code] = nil
			elseif gameRelease then send(gameRelease, "Up") end
		end)
		if not ok then state.lastError = tostring(err) end
	end
	local function releaseClick()
		local payload = clickHeld
		clickHeld = nil
		if not payload then return end
		local ok, err = pcall(send, payload, "Up")
		if not ok then state.lastError = tostring(err) end
	end
	local function release() releaseKey(); releaseClick() end
	function api:_resetSurvival(cancelOwner, resumed)
		local wasActive = self._survival.active
		self._survival.active, self._survival.character, self._survival.healthySince = false, character, nil
		state.survivalActive, state.survivalSince = false, nil
		if wasActive and cancelOwner then
			cancelMove(); releaseFacing(); routeRequest, targetSample = nil, nil; nextMove = 0
		end
		if wasActive and resumed then state.survivalResumes += 1 end
	end
	function api:_updateSurvival(now, hum)
		local health, maximum = hum.Health, hum.MaxHealth
		if health ~= health or maximum ~= maximum or maximum <= 0 or maximum == math.huge then
			state.survivalHealth = nil
			return false
		end
		local ratio = math.clamp(health / maximum, 0, 1)
		state.survivalHealth = ratio * 100
		if self._survival.character ~= character then
			self._survival.active, self._survival.character, self._survival.healthySince = false, character, nil
			state.survivalActive, state.survivalSince = false, nil
		end
		if not options.godMode or suspended or not activeFarm()
			or game.PlaceId ~= 914010731 or game.GameId ~= 380704901 then
			if self._survival.active then self:_resetSurvival(true, false) end
			return false
		end
		if not self._survival.active and target and ratio <= 0.5 then
			self._survival.active, self._survival.healthySince = true, nil
			state.survivalActive, state.survivalSince = true, now
			state.survivalRetreats += 1
			-- Keep the target/farm lock, but retire every combat and movement owner
			-- before the emergency route is rebuilt on the next block below.
			release(); cancelMove(true); releaseFacing()
			routeRequest, targetSample, nextMove = nil, nil, 0
		end
		if not self._survival.active then return false end
		if ratio >= 0.85 then
			self._survival.healthySince = self._survival.healthySince or now
			if now - self._survival.healthySince >= 1 then
				self:_resetSurvival(true, true)
				state.survivalHealth = ratio * 100
				return false
			end
		else
			self._survival.healthySince = nil
		end
		state.survivalActive = true
		return true
	end
	local function click(now, aim)
		if absorptionBlocked(now) or clickHeld or now < nextClick then return end
		if activeFarm() and target and safeZoneBlocked(target, now) then skipProtected(target, now); return end
		local payload = inputPayload(0x01, aim)
		if not payload then return end
		-- M1 is game-only, including standalone AutoClick. Never fall back to
		-- an OS click: that would activate whichever GUI is under the cursor.
		-- Separate ownership from skill/equipment keys; no shared input lock.
		clickHeld, clickReleaseAt = payload, now + 0.01
		send(payload, "Down")
		state.clickAttempts += 1
		noteCombatAttempt(now)
		-- No cooldown reservation or catch-up burst. These are input attempts,
		-- not a promise that the weapon/server accepts every click.
		nextClick = now + options.clickInterval
	end
	local function pulse(code, now, aim, untracked)
		if absorptionBlocked(now) or held or now < nextInput then return false end
		local attack = code == 0x45 or code == 0x52 or code == 0x46 or code == 0x43
		if attack and not untracked and target and safeZoneBlocked(target, now) then skipProtected(target, now); return false end
		-- Equip digits 1–9 stay native while focused; farm attacks never move the OS cursor.
		local equipDigit = code >= 0x31 and code <= 0x39
		local direct = (activeFarm() and not equipDigit) or not isrbxactive()
		local payload = direct and inputPayload(code, aim, untracked) or nil
		if not payload and not isrbxactive() then return false end
		if not payload then
			flushNativeReleases()
			if nativeReleases[code] then return false end
			nativeReleases[code] = true
		end
		held, releaseAt, nextInput = code, now + 0.06, now + 0.15
		heldRemote = payload
		heldGameRelease = not payload and inputPayload(code, aim, untracked) or nil
		if payload then send(payload, "Down") else keypress(code) end
		if attack and not untracked then noteCombatAttempt(now) end
		return true
	end
	local function allowed()
		if not alive() then return false, "Stopped" end
		if game.PlaceId ~= 914010731 or game.GameId ~= 380704901 then return false, "Unsupported game" end
		if suspended then return false, "Suspended" end
		if GuiService.MenuIsOpen then return false, "Menu open" end
		if not isrbxactive() and not gameInput() then return false, "Roblox unfocused" end
		if Input:GetFocusedTextBox() then return false, "Typing" end
		return true, "Active"
	end
	local function stepTrainer(now, folder)
		if not options.autoTrainer or api._trainer.busy or now < nextTrainer then return end
		local session = trainerSessionActive()
		if session then
			local name = currentTrainer(folder)
			if name then
				local _, _, progress = trainerEntry(folder, name)
				state.trainerTarget, state.trainerProgress = name, progress
			end
			local attempt = api._trainerSessions[session]
			if attempt and (attempt.active or now - attempt.at < 12) then
				state.trainerFinishMode = attempt.mode or api._trainer.finishMode
				state.trainerStatus = attempt.active and "Completing training" or "Finishing training"
				nextTrainer = now + 0.25
				return
			end
			if attempt then api._trainerSessions[session] = nil end
			local completion, completionError, finishMode = api:_trainerDispatcher(session)
			if not completion then
				state.trainerStatus = "Waiting for training client"
				state.trainerResponse = completionError
				nextTrainer = now + (completionError and 2 or 0.1)
				return
			end
			local token, entry = {}, { active = true, at = now, mode = finishMode }
			api._trainer.completionToken, api._trainerSessions[session] = token, entry
			api._trainer.finishMode, state.trainerFinishMode = finishMode, finishMode
			api:_updateTrainerBusy()
			state.trainerStatus, state.trainerResponse = "Completing training", nil
			state.trainerCompletionAttempts += 1
			task.spawn(function()
				local ok, response = pcall(completion)
				if finishMode == "TSCodeVal" then api._trainer.code, api._trainer.codeCharacter = nil, nil end
				entry.active, entry.at, entry.ok = false, os.clock(), ok
				if not ok then api._trainerSessions[session] = nil end
				if api._trainer.completionToken ~= token then return end
				api._trainer.completionToken = nil; api:_updateTrainerBusy()
				if not alive() or not options.autoTrainer then return end
				if ok then
					state.trainerCompleted += 1
					state.trainerStatus, state.trainerResponse = "Finishing training", "COMPLETED"
					nextTrainer = os.clock() + 0.25
				else
					state.trainerStatus = "Trainer error"
					state.trainerResponse = tostring(response)
					state.lastError = "Trainer completion: " .. tostring(response)
					nextTrainer = os.clock() + 3
				end
			end)
			return
		end
		local name, progress, issue = pickTrainer(folder)
		state.trainerTarget, state.trainerProgress = name, progress
		if issue then
			state.trainerStatus, state.trainerResponse = issue, nil
			nextTrainer = now + (issue == "All trainers complete" and 5 or 2)
			return
		end
		local remotes = ReplicatedStorage:FindFirstChild("Remotes")
		local group = remotes and remotes:FindFirstChild("Trainers")
		local change = group and group:FindFirstChild("ChangeTrainer")
		local request = group and group:FindFirstChild("RequestTraining")
		if not request or not (request:IsA("RemoteFunction") or request:IsA("RemoteEvent")) then
			state.trainerStatus = "Waiting for trainer remote"
			nextTrainer = now + 2
			return
		end
		local token, expectedCharacter = {}, character
		api._trainer.token = token; api:_updateTrainerBusy()
		state.trainerStatus, state.trainerResponse = "Starting trainer", nil
		state.trainerAttempts += 1
		task.spawn(function()
			local ok, response = pcall(function()
				if not alive() or api._trainer.token ~= token or not options.autoTrainer or player.Character ~= expectedCharacter then return "CANCELLED" end
				if change and (change:IsA("RemoteFunction") or change:IsA("RemoteEvent")) and currentTrainer(folder) ~= name then
					-- ChangeTrainer is a RemoteFunction whose server-side change can replicate
					-- before InvokeServer returns (and some servers never return it at all).
					-- Observe the replicated trainer value instead of blocking the controller.
					local finished, succeeded, result = false, false, nil
					task.spawn(function()
						succeeded, result = pcall(trainerRemote, change, name)
						finished = true
					end)
					local deadline = os.clock() + 3
					repeat
						if not alive() or api._trainer.token ~= token or not options.autoTrainer or player.Character ~= expectedCharacter then return "CANCELLED" end
						if currentTrainer(folder) == name then break end
						if finished and not succeeded then error(result) end
						task.wait(0.05)
					until os.clock() >= deadline
					if currentTrainer(folder) ~= name then return finished and tostring(result) or "CHANGE_TIMEOUT" end
				end
				if not alive() or api._trainer.token ~= token or not options.autoTrainer or player.Character ~= expectedCharacter then return "CANCELLED" end
				api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
				state.trainerFinishMode = nil
				local finished, succeeded, result = false, false, nil
				task.spawn(function()
					succeeded, result = pcall(trainerRemote, request)
					finished = true
				end)
				local deadline = os.clock() + 3
				repeat
					if not alive() or api._trainer.token ~= token or not options.autoTrainer or player.Character ~= expectedCharacter then return "CANCELLED" end
					if trainerSessionActive() then return "TRAINING" end
					if finished and not succeeded then error(result) end
					if finished and result ~= nil then return result end
					task.wait(0.05)
				until os.clock() >= deadline
				return finished and result or "REQUEST_TIMEOUT"
			end)
			if api._trainer.token ~= token then return end
			api._trainer.token = nil; api:_updateTrainerBusy()
			if not alive() or not options.autoTrainer or player.Character ~= expectedCharacter then return end
			if ok then
				local text = tostring(response)
				state.trainerResponse = text
				if response == "TRAINING" or response == true or text == "SUCCESS" or text == "SENT" then
					state.trainerAccepted += 1
					state.trainerStatus = "Training"
					nextTrainer = os.clock() + 0.05
				else
					state.trainerStatus = "Trainer waiting"
					nextTrainer = os.clock() + 4
				end
			else
				state.trainerStatus = "Trainer error"
				state.lastError = "Trainer: " .. tostring(response)
				nextTrainer = os.clock() + 5
			end
		end)
	end
	local function equipmentStatus(now)
		local folder = player:FindFirstChild("PlayerFolder")
		local control = character and character:FindFirstChild("ServerControl")
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local stat = folder and folder:FindFirstChild("ArataStat")
		local arataFlag = control and control:FindFirstChild("ArataOn")
		local maskFlag = folder and folder:FindFirstChild("Mask")
		-- Confirmation belongs to this life and these replicated objects, not a
		-- previous character's flags or an input-attempt counter.
		if equipment.character ~= character or equipment.hum ~= hum or equipment.folder ~= folder
			or equipment.control ~= control or equipment.stat ~= stat or equipment.arataFlag ~= arataFlag
			or equipment.maskFlag ~= maskFlag then
			equipment = { character = character, hum = hum, folder = folder, control = control,
				stat = stat, arataFlag = arataFlag, maskFlag = maskFlag }
			nextArata, nextMask, lastEquipmentKey = 0, 0, nil
		end
		local arataOn, maskOn = value(control, "ArataOn"), value(folder, "Mask")
		state.arataEquipped, state.maskEquipped = arataOn == true, maskOn == true
		if arataOn == true then equipment.arataSince = equipment.arataSince or now else equipment.arataSince = nil end
		if maskOn == true then equipment.maskSince = equipment.maskSince or now else equipment.maskSince = nil end
		local team, arata = value(control, "Team"), value(stat, "Arata")
		local applicable = team == "CCG"
		local knownTeam = type(team) == "string" and team ~= ""
		local owned = type(arata) == "string" and arata ~= "" and arata ~= "None"
		-- A short stable observation rejects transient/stale replication. It is
		-- not a fixed post-key delay: false/missing flags keep the gate closed.
		local arataReady = not options.autoArata or knownTeam and not applicable
			or applicable and owned and equipment.arataSince ~= nil and now - equipment.arataSince >= 0.25
		local maskReady = not options.autoMask or equipment.maskSince ~= nil and now - equipment.maskSince >= 0.25
		local reason = not arataReady and (not knownTeam and "Waiting for equipment state"
			or not owned and "Arata unavailable" or "Equipping Arata")
			or not maskReady and "Equipping mask" or nil
		state.equipmentReady, state.equipmentPreparing = arataReady and maskReady, activeFarm() and not (arataReady and maskReady)
		return arataReady and maskReady, reason,
			options.autoArata and applicable and owned and arataOn == false,
			options.autoMask and maskOn == false
	end
	local function deferSafetyRetry(now)
		if now - lastBackoff > 30 then recoveryLevel = 0 end
		recoveryLevel = math.min(4, recoveryLevel + 1); lastBackoff = now
		local delay = 2 ^ (recoveryLevel - 1)
		state.recoveryDelay, recoveryAt = delay, now + delay
		state.recoveryBackoffs += 1
	end
	local function interruptMove(message, kind)
		release(); cancelMove(); releaseFacing()
		routeRequest, routeBlocked, targetSample = nil, nil, nil
		-- Keep the user's switch/intent. The fault gates every action until a
		-- fresh route from the ACTUAL position passes all existing safety checks.
		local now = os.clock()
		moveFault = { character = character, humanoid = characterHumanoid, kind = kind or "route" }
		deferSafetyRetry(now)
		state.safetyPauses += 1
		state.lastSafetyPause = { kind = moveFault.kind, message = message, at = now,
			lockId = farmLock and farmLock.id, target = targetLabel(target) }
		state.reason, state.lastError = "Safety pause", message
	end
	local function unsafePart(part)
		local ancestor = part
		while ancestor and ancestor ~= Workspace do
			local name = string.lower(ancestor.Name)
			if string.find(name, "barrier", 1, true) or string.find(name, "boundary", 1, true)
				or string.match(name, "^kill") or string.match(name, "^death") or name == "void" then return true end
			ancestor = ancestor.Parent
		end
		return false
	end
	local function floorParams()
		local exclude = { character }
		local spawns = Workspace:FindFirstChild("NPCSpawns")
		if spawns then table.insert(exclude, spawns) end
		for _, other in ipairs(Players:GetPlayers()) do
			if other.Character then table.insert(exclude, other.Character) end
		end
		for _, child in ipairs(Workspace:GetChildren()) do
			if child:IsA("Model") and child:FindFirstChildOfClass("Humanoid") then table.insert(exclude, child) end
		end
		local params = RaycastParams.new()
		params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, exclude
		params.RespectCanCollide = true
		return params
	end
	local function validPoint(point)
		if point.X ~= point.X or point.Y ~= point.Y or point.Z ~= point.Z
			or math.abs(point.X) == math.huge or math.abs(point.Y) == math.huge or math.abs(point.Z) == math.huge
			or point.Y <= Workspace.FallenPartsDestroyHeight + 32 then return false end
		return true
	end
	-- v7510 exposes floor indicators, not server immunity or attacker credit.
	-- Their oriented footprint is a conservative exclusion, with bounded Y.
	local zoneContainer, zoneParts = nil, {}
	local combatProgress = setmetatable({}, { __mode = "k" })
	local function registerZone(part)
		if zoneContainer and part.Name == "SafeZoneIndicator" and part:IsA("BasePart")
			and part:IsDescendantOf(zoneContainer) then zoneParts[part] = true end
	end
	local function syncSafeZones()
		zoneContainer = Workspace:FindFirstChild("SafeZones")
		table.clear(zoneParts)
		if zoneContainer then
			for _, part in ipairs(zoneContainer:GetDescendants()) do registerZone(part) end
		end
	end
	local function safeZoneAt(root)
		if Workspace:FindFirstChild("SafeZones") ~= zoneContainer then syncSafeZones() end
		local count, zone = 0, nil
		for part in pairs(zoneParts) do
			if part:IsDescendantOf(zoneContainer) and part.Name == "SafeZoneIndicator" then
				local size = part.Size
				if validPoint(part.Position) and size.X > 0 and size.Y > 0 and size.Z > 0
					and size.X < math.huge and size.Y < math.huge and size.Z < math.huge then
					count += 1
					if root and validPoint(root.Position) then
						local p = part.CFrame:PointToObjectSpace(root.Position)
						-- Standing rigs need more than the thin mesh slab. Never
						-- project a rooftop indicator infinitely down to street level.
						if math.abs(p.X) <= size.X / 2 + 1 and math.abs(p.Z) <= size.Z / 2 + 1
							and math.abs(p.Y) <= size.Y / 2 + 8 then zone = part end
					end
				end
			else zoneParts[part] = nil end
		end
		state.safeZoneParts, state.safeZoneDataReady = count, count > 0
		return zone, count > 0
	end
	local function progressEntry(model, hum, root)
		local playerHum = character and character:FindFirstChildOfClass("Humanoid")
		local entry = combatProgress[model]
		if not entry or entry.hum ~= hum or entry.root ~= root or entry.parent ~= model.Parent
			or entry.character ~= character or entry.playerHum ~= playerHum then
			entry = { hum = hum, root = root, parent = model.Parent,
				character = character, playerHum = playerHum, health = hum.Health }
			combatProgress[model] = entry
		end
		return entry
	end
	local function sampleCombatProgress(model, hum, root, now)
		local entry = progressEntry(model, hum, root)
		local health = hum.Health
		local playerRoot = character and character:FindFirstChild("HumanoidRootPart")
		if health == health and health > 0 and health < math.huge then
			-- Reduced starting HP, an earlier foreign hit and a sent request
			-- are not engagement. A fresh in-range correlation is still NOT
			-- authoritative proof this player caused the decrease.
			if entry.health and health < entry.health and entry.attemptAt and now >= entry.attemptAt
				and now - entry.attemptAt <= 1 and target == model and activeFarm() and allowed()
				and not absorption.pending and living(entry.playerHum) and playerRoot
				and (playerRoot.Position - root.Position).Magnitude <= 6 then entry.damageAt = now end
			entry.health = health
		else entry.damageAt, entry.attemptAt = nil, nil end
		return entry
	end
	safeZoneBlocked = function(model, now)
		if not model or kind(model) == "Corpse" then return false end
		local hum, root = model:FindFirstChild("Humanoid"), model:FindFirstChild("HumanoidRootPart")
		if not hum or not hum:IsA("Humanoid") or not root or not root:IsA("BasePart") then return false end
		local entry = sampleCombatProgress(model, hum, root, now)
		local zone, known = safeZoneAt(root)
		if not known then return true, "Waiting for safe zone data" end
		if zone and not (entry.damageAt and now - entry.damageAt < 3) then return true, "Target in safe zone", zone end
		return false, nil, zone
	end
	noteCombatAttempt = function(now)
		if not target or not activeFarm() or kind(target) == "Corpse" then return end
		local hum, root = target:FindFirstChild("Humanoid"), target:FindFirstChild("HumanoidRootPart")
		local playerRoot = character and character:FindFirstChild("HumanoidRootPart")
		if hum and hum:IsA("Humanoid") and root and playerRoot and (root.Position - playerRoot.Position).Magnitude <= 6 then
			local entry = sampleCombatProgress(target, hum, root, now)
			entry.attemptAt = now
		end
	end
	local function floorAt(point, params)
		if not validPoint(point) then return nil, "Недопустимая высота / пустота" end
		-- Start near the root, not above the ceiling of the current room.
		local hit = Workspace:Raycast(point + Vector3.new(0, 0.5, 0), Vector3.new(0, -48, 0), params)
		if not hit or unsafePart(hit.Instance) or hit.Normal.Y < 0.65
			or (hit.Instance:IsA("BasePart") and not hit.Instance.Anchored) then return nil, "Нет безопасной опоры" end
		if hit.Position.Y <= Workspace.FallenPartsDestroyHeight + 32 then return nil, "Опора слишком близко к пустоте" end
		return hit.Position
	end
	local function rootClearance(hum, root)
		local height = hum.HipHeight + root.Size.Y * 0.5
		if hum.RigType == Enum.HumanoidRigType.R6 then
			local leg = character:FindFirstChild("Left Leg")
			if not leg or not leg:IsA("BasePart") then return nil end
			height += leg.Size.Y
		end
		return height > 0 and height < 30 and height or nil
	end
	local hazards = {}
	local function registerHazard(part)
		if part:IsA("BasePart") and not part:IsDescendantOf(character) and unsafePart(part) then hazards[part] = true end
	end
	for _, part in ipairs(Workspace:GetDescendants()) do registerHazard(part) end
	local function hazardIntersects(part, origin, goal, size)
		-- Conservative oriented-box sweep of KNOWN hazard volumes, including CanQuery=false.
		local frame, half = part.CFrame, size * 0.5
		local function projection(axis) return math.abs(axis.X) * half.X + math.abs(axis.Y) * half.Y + math.abs(axis.Z) * half.Z end
		local extent = part.Size * 0.5 + Vector3.new(projection(frame.RightVector), projection(frame.UpVector), projection(frame.LookVector))
		local start, delta = frame:PointToObjectSpace(origin), frame:VectorToObjectSpace(goal - origin)
		local near, far = 0, 1
		for _, axis in ipairs({ "X", "Y", "Z" }) do
			local p, d, e = start[axis], delta[axis], extent[axis]
			if math.abs(d) < 0.000001 then
				if math.abs(p) > e then return false end
			else
				local a, b = (-e - p) / d, (e - p) / d
				near, far = math.max(near, math.min(a, b)), math.min(far, math.max(a, b))
				if near > far then return false end
			end
		end
		return true
	end
	local function bodyRoute(origin, goal, clearance, params)
		local size = Vector3.new(4, math.max(2, clearance * 2 - 0.6), 4)
		-- This is scoped no-collision travel, NOT walking. Tables, walls and ceilings
		-- must not force a navmesh route (Anteiku has no usable Walk-only exit).
		local delta = goal - origin
		-- Roblox shapecasts have a1024-stud direction limit. Long cross-map
		-- cruise legs must be split, even though ordinary solids are ignored.
		if delta.Magnitude > 0.01 then
			local count = math.ceil(delta.Magnitude / 512)
			for index = 1, count do
				local start = origin:Lerp(goal, (index - 1) / count)
				local hit = Workspace:Blockcast(CFrame.new(start), size, delta / count, params)
				if hit and unsafePart(hit.Instance) then return false, "На маршруте опасная зона / барьер" end
			end
		end
		for part in pairs(hazards) do
			if part.Parent and not part:IsDescendantOf(character) and hazardIntersects(part, origin, goal, size) then
				return false, "На маршруте опасная зона / барьер"
			end
		end
		return true
	end
	local function validateSegment(origin, goal, clearance, params, requireSupport)
		if not validPoint(origin) or not validPoint(goal) then return false, "Недопустимая высота / пустота" end
		local delta = goal - origin
		-- A controlled no-collision flight does not need walkable ground below
		-- every intermediate frame. Keep that check only for choosing a ground
		-- approach / navmesh path; landing support is checked independently.
		if requireSupport == false then return bodyRoute(origin, goal, clearance, params) end
		local count = math.max(1, math.ceil(delta.Magnitude / 4))
		local horizontal = Vector3.new(delta.X, 0, delta.Z)
		local side = horizontal.Magnitude > 0.01 and Vector3.new(-horizontal.Z, 0, horizontal.X).Unit * 2 or Vector3.new(2, 0, 0)
		for index = 0, count do
			local point = origin:Lerp(goal, index / count)
			for _, offset in ipairs({ Vector3.zero, side, -side }) do
				local support, why = floorAt(point + offset, params)
				if not support then return false, why end
				local drop = point.Y - support.Y
				if drop < clearance - 1 or drop > 24 then return false, "Маршрут пересекает пол / обрыв" end
			end
			if index > 0 then
				local safe, why = bodyRoute(origin:Lerp(goal, (index - 1) / count), point, clearance, params)
				if not safe then return false, why end
			end
		end
		return true
	end
	local function landingAt(goal, clearance, params)
		local floor, err = floorAt(goal, params)
		if not floor then return nil, err end
		if goal.Y - floor.Y > 24 then return nil, "Место приземления слишком далеко под целью" end
		goal = Vector3.new(goal.X, floor.Y + clearance + 0.1, goal.Z)
		for _, offset in ipairs({ Vector3.new(2, 0, 0), Vector3.new(-2, 0, 0), Vector3.new(0, 0, 2), Vector3.new(0, 0, -2) }) do
			local support = floorAt(goal + offset, params)
			if not support or goal.Y - support.Y < clearance - 1 or goal.Y - support.Y > 24 then
				return nil, "Недостаточно опоры в месте приземления"
			end
		end
		return goal
	end
	local function safeRoute(origin, goal, root, hum, floating)
		local params = floorParams()
		local clearance = rootClearance(hum, root)
		if not clearance then return nil, "Неполный / неизвестный риг" end
		if not floating then
			local landing, err = landingAt(goal, clearance, params)
			if not landing then return nil, err end
			goal = landing
		end
		local delta = goal - origin
		if delta.Magnitude > 3200 then return nil, "Маршрут слишком длинный для безопасной проверки" end
		local safe, why = validateSegment(origin, goal, clearance, params, not floating)
		if safe then return goal end
		-- A raised room or changing terrain can make a walking route impossible.
		-- Cruise above the endpoints, then descend at the supported destination;
		-- ordinary floors/walls and missing ground in transit do not veto flight.
		for _, lift in ipairs({ 4, 8, 12 }) do
			local height = math.max(origin.Y, goal.Y) + lift
			local points = { origin }
			for _, point in ipairs({ Vector3.new(origin.X, height, origin.Z), Vector3.new(goal.X, height, goal.Z), goal }) do
				if (point - points[#points]).Magnitude > 0.01 then table.insert(points, point) end
			end
			local lengths, length, valid = { 0 }, 0, true
			for index = 2, #points do
				local safeLeg = validateSegment(points[index - 1], points[index], clearance, params, false)
				if not safeLeg then valid = false; break end
				length += (points[index] - points[index - 1]).Magnitude; lengths[index] = length
			end
			if valid and #points > 1 and length <= 3200 then
				return goal, nil, { points = points, lengths = lengths, length = length, goal = goal }
			end
		end
		return nil, why
	end
	local function approachRoute(origin, desired, root, hum, bossRoot, spacing, floating)
		local position, why, route = safeRoute(origin, desired, root, hum, floating)
		if position or floating then return position, why, route end
		local clearance, params = rootClearance(hum, root), floorParams()
		if not clearance then return nil, why end
		-- Behind is preferred, not a command to land beyond a trench/platform
		-- edge. Keep the full support margin and hazard sweep for every candidate.
		-- A failed Walk navmesh cannot repair an unsupported endpoint.
		local navigationGoal = landingAt(desired, clearance, params)
		local center = bossRoot.Position
		local toward = Vector3.new(origin.X - center.X, 0, origin.Z - center.Z)
		local offsets = {}
		if toward.Magnitude > 0.01 then table.insert(offsets, toward.Unit * spacing) end
		local behind = Vector3.new(desired.X - center.X, 0, desired.Z - center.Z)
		if behind.Magnitude < 0.01 then behind = Vector3.new(0, 0, 1) end
		behind = behind.Unit * spacing
		for _, degrees in ipairs({45, -45, 90, -90, 135, -135, 180}) do
			table.insert(offsets, CFrame.Angles(0, math.rad(degrees), 0):VectorToWorldSpace(behind))
		end
		for _, offset in ipairs(offsets) do
			local candidate = center + offset
			local landing = landingAt(candidate, clearance, params)
			if landing then
				navigationGoal = navigationGoal or landing
				position, _, route = safeRoute(origin, candidate, root, hum, false)
				if position then return position, nil, route end
			end
		end
		return nil, why, nil, navigationGoal
	end
	local function navigationRoute(origin, goal, root, hum, model)
		if routeRequest then
			local request = routeRequest
			if request.target ~= model then
				routeRequest = nil
			elseif not request.done then return nil, "Planning route"
			else
				routeRequest = nil
				if not request.points then return nil, "Unsafe route", request.error end
				local clearance, params = rootClearance(hum, root), floorParams()
				if not clearance then return nil, "Unsafe route" end
				local points, length = { origin }, 0
				local mapped = {}
				for _, waypoint in ipairs(request.points) do
					if waypoint.Action ~= Enum.PathWaypointAction.Walk then return nil, "Unsafe route" end
					local point = waypoint.Position + Vector3.new(0, clearance, 0)
					local floor = floorAt(point, params)
					if not floor then return nil, "Unsafe route" end
					point = Vector3.new(point.X, floor.Y + clearance + 0.1, point.Z)
					table.insert(mapped, point)
				end
				-- Start at a safely connectable nearby waypoint, not the obsolete request origin.
				local first, best = nil, math.huge
				for index, point in ipairs(mapped) do
					local distance = (point - origin).Magnitude
					if distance < best and validateSegment(origin, point, clearance, params) then first, best = index, distance end
				end
				if not first then return nil, "Unsafe route" end
				for index = first, #mapped do
					if (mapped[index] - points[#points]).Magnitude > 0.2 then table.insert(points, mapped[index]) end
				end
				local floor = floorAt(goal, params)
				if floor then
					local latest = Vector3.new(goal.X, floor.Y + clearance + 0.1, goal.Z)
					if validateSegment(points[#points], latest, clearance, params) then table.insert(points, latest) end
				end -- An old but useful validated prefix may be followed while a new suffix is planned.
				if #points < 2 then return nil, "Unsafe route" end
				local lengths = { 0 }
				for index = 2, #points do
					local safe = validateSegment(points[index - 1], points[index], clearance, params)
					if not safe then return nil, "Unsafe route" end
					length += (points[index] - points[index - 1]).Magnitude; lengths[index] = length
					if length > 3200 then return nil, "Unsafe route" end
				end
				return { points = points, lengths = lengths, length = length, goal = points[#points] }
			end
		end
		if navigationBusy then return nil, "Planning route" end
		local request = { origin = origin, goal = goal, target = model, character = character }
		routeRequest, navigationBusy = request, true
		task.spawn(function()
			if not alive() or routeRequest ~= request then navigationBusy = false; return end
			local path, points
			local ok, err = pcall(function()
				path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = math.ceil(math.max(6, (rootClearance(hum, root) or 3) * 2)),
					AgentCanJump = false, AgentCanClimb = false, WaypointSpacing = 4 })
				path:ComputeAsync(origin, goal)
				if path.Status == Enum.PathStatus.Success then points = path:GetWaypoints() end
			end)
			local failure = not ok and tostring(err) or (not points and "Навигация не нашла путь (NoPath)" or nil)
			if path then pcall(function() path:Destroy() end) end
			if not ok then points = nil end
			navigationBusy = false
			if alive() and routeRequest == request and character == request.character then request.points, request.done, request.error = points, true, failure end
		end)
		return nil, "Planning route"
	end
	local function applyMove()
		local owner = movement or hover
		if not owner then return end
		if pollLock then pollLock() end
		refreshCharacter()
		if absorptionBlocked(os.clock()) then release(); cancelMove(); releaseFacing(); routeRequest = nil; return end
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local safe = allowed()
		local emergency = api._survival.active and options.godMode and not suspended
			and game.PlaceId == 914010731 and game.GameId == 380704901
		if not safe and not emergency then table.clear(combatProgress) end
		if not safe and not emergency or character ~= player.Character or not living(hum)
			or owner.root ~= character:FindFirstChild("HumanoidRootPart") then release(); cancelMove(); return end
		if not emergency and not equipmentStatus(os.clock()) then release(); cancelMove(); releaseFacing(); routeRequest = nil; return end
		local bossHum, bossRoot = bossParts(owner.target)
		if owner.target.Parent ~= owner.targetParent or not bossHum or bossRoot ~= owner.bossRoot
			or not selected(owner.target) then release(); cancelMove(); releaseFacing(); return end
		if not emergency and safeZoneBlocked(owner.target, os.clock()) then skipProtected(owner.target, os.clock()); return end
		-- Check actual displacement BEFORE writing a new frame, so a driver cannot hide a correction.
		local shift = (owner.root.Position - owner.lastApplied).Magnitude
		if shift > math.max(12, math.min(24, options.moveSpeed * 0.06)) then
			local now = os.clock()
			for index = #displacementTimes, 1, -1 do
				if now - displacementTimes[index] > 3 then table.remove(displacementTimes, index) end
			end
			table.insert(displacementTimes, now); state.lastDisplacement = shift
			-- Never overwrite the external position. Repeated moderate shifts pause
			-- with bounded backoff instead of silently switching off the user's farm.
			-- Large shifts also cancel BEFORE any write and require a fresh safe route.
			if shift > 64 then
				interruptMove("Большое внешнее смещение (>64 studs): пауза и проверка нового пути от фактической позиции.", "displacement")
			else
				release(); cancelMove(); releaseFacing(); routeRequest, routeBlocked, targetSample = nil, nil, nil
				local delay = 0.2
				if #displacementTimes >= 3 then
					if now - lastBackoff > 30 then recoveryLevel = 0 end
					recoveryLevel = math.min(4, recoveryLevel + 1); lastBackoff = now
					delay = 2 ^ (recoveryLevel - 1); state.recoveryBackoffs += 1
					table.clear(displacementTimes)
				end
				state.recoveryDelay, recoveryAt = delay, now + delay; state.movementRecoveries += 1
				state.reason = "Recovering position"
				state.lastError = delay > 0.2 and "Повторные смещения: временная пауза, затем новый Tween от фактической позиции."
					or "Внешнее смещение: маршрут пересчитывается от текущей позиции."
			end
			return
		end
		local point = owner.driver and owner.driver.Value or owner.lastApplied
		local displacements = {}
		if owner.route then
			local alpha = (point - owner.origin).Magnitude / math.max(0.001, (owner.driverGoal - owner.origin).Magnitude)
			local travelled = math.clamp(alpha, 0, 1) * owner.route.length
			for index = 2, #owner.route.points do
				if owner.route.lengths[index] > owner.travelled and owner.route.lengths[index] < travelled then
					table.insert(displacements, { point = owner.route.points[index], distance = owner.route.lengths[index] })
				end
				if travelled <= owner.route.lengths[index] then
					local start = owner.route.lengths[index - 1]
					point = owner.route.points[index - 1]:Lerp(owner.route.points[index], (travelled - start) / math.max(0.001, owner.route.lengths[index] - start))
					break
				end
			end
			table.insert(displacements, { point = point, distance = travelled })
		else table.insert(displacements, { point = point })
		end
		local clearance, params = rootClearance(hum, owner.root), floorParams()
		local landing = not owner.floating and floorAt(owner.goal, params)
		if not clearance or (not owner.floating and (not landing or owner.goal.Y - landing.Y < clearance - 1 or owner.goal.Y - landing.Y > 24)) then
			interruptMove("Место приземления стало небезопасным: ожидание безопасного нового пути.", "landing")
			return
		end
		noCollision()
		for _, displacement in ipairs(displacements) do
			local valid = validateSegment(owner.lastApplied, displacement.point, clearance, params, false)
			if not valid then
				interruptMove("Опасная зона / небезопасная высота: ожидание безопасного нового пути.", "route")
				return
			end
		-- Tween a value, not BasePart.Position: CFrame moves the connected assembly intact.
		-- Requested facing is independent of the position driver and uses the live boss.
			owner.root.CFrame = facingFrame(displacement.point, owner.bossRoot, owner.root.CFrame)
			owner.root.AssemblyLinearVelocity = Vector3.zero
			owner.lastApplied, owner.travelled = displacement.point, displacement.distance or 0
		end
		if owner.finished then
			local floating = owner.floating
			cancelMove(floating)
			if floating then
				owner.driver, owner.tween, owner.completed, owner.finished, owner.route = nil, nil, nil, nil, nil
				hover = owner; state.holdingPosition = true
			end
		end
	end
	local cooldownNames = { "ClickCD", "Special1CD", "Special2CD", "Special3CD", "SpecialBonusCD" }
	local function disconnectLinks(links)
		for _, connection in ipairs(links) do connection:Disconnect() end
		table.clear(links)
	end
	local function clearCooldowns()
		for _, entry in pairs(recharge) do disconnectLinks(entry.links) end
		table.clear(recharge); disconnectLinks(cooldownFolderLinks); cooldownFolder = nil
	end
	local function listen(links, signal, callback)
		if signal then table.insert(links, signal:Connect(function(...) if alive() then callback(...) end end)) end
	end
	local bindCooldown
	bindCooldown = function(name)
		local child = cooldownFolder and cooldownFolder:FindFirstChild(name)
		local cd = child and child:FindFirstChild("CD")
		local old = recharge[name]
		if old and old.child == child and old.cdObject == cd then return old end
		if old then disconnectLinks(old.links); recharge[name] = nil end
		if not child then return end
		local entry = { child = child, cdObject = cd, links = {} }
		recharge[name] = entry
		local function update()
			if recharge[name] ~= entry then return end
			local setting = child.Value
			local seconds = cd and tonumber(cd.Value) or nil
			if type(setting) == "string" and string.sub(setting, 1, 8) == "Refresh|" then seconds = tonumber(string.sub(setting, 9)) end
			entry.setting, entry.cd = setting, cd and cd.Value
			entry.readyAt = seconds and seconds >= 0 and seconds < math.huge and os.clock() + seconds or math.huge
		end
		entry.update = update; update()
		listen(entry.links, child.Changed, update)
		listen(entry.links, child.AttributeChanged, update)
		listen(entry.links, cd and cd.Changed, update)
		local function changedObject(object) if object.Name == "CD" then bindCooldown(name) end end
		listen(entry.links, child.ChildAdded, changedObject)
		listen(entry.links, child.ChildRemoved, changedObject)
		return entry
	end
	local function syncCooldowns(folder)
		if cooldownFolder ~= folder then
			clearCooldowns(); cooldownFolder = folder
			local function changedChild(child)
				for _, name in ipairs(cooldownNames) do if child.Name == name then bindCooldown(name); break end end
			end
			listen(cooldownFolderLinks, folder.ChildAdded, changedChild)
			listen(cooldownFolderLinks, folder.ChildRemoved, changedChild)
		end
		for _, name in ipairs(cooldownNames) do
			local entry = bindCooldown(name)
			if entry and (entry.setting ~= entry.child.Value or entry.cd ~= (entry.cdObject and entry.cdObject.Value)) then entry.update() end
		end
	end
	local function ready(folder, name, now)
		local setting = value(folder, name)
		if setting == "Ready" then return true end
		local entry = recharge[name]
		return entry ~= nil and (setting == "Recharge" or (type(setting) == "string" and string.sub(setting, 1, 8) == "Refresh|"))
			and now >= entry.readyAt
	end
	function api:_stepCToggle(now, folder, root, canAct, blocked)
		if blocked or not canAct or not options.skills.C or options.cMode ~= "Toggle"
			or now < nextSkill or not ready(folder, cooldowns.C, now) then return false end
		local weapon = equippedWeapon()
		if not weapon or cToggles[character] == true then return false end
		local _, aimRoot = bossParts(target)
		local aim = aimRoot and aimRoot.Position or root.Position + root.CFrame.LookVector * 10
		-- Toggle is character setup, not an attack attempt. Dispatch it without
		-- target/safe-zone ownership so respawn recovery and route pauses cannot starve it.
		if not pulse(keycodes.C, now, aim, true) then return false end
		cToggles[character], state.cToggleSent = true, true
		state.skillAttempts += 1; state.skillAttemptsByKey.C += 1; state.lastSkillKey = "C"
		nextSkill, skillIndex = now + options.skillInterval, 4
		return true
	end
	bossParts = function(model)
		if pendingCorpse and model == pendingCorpse.model then
			local entry = pendingCorpse
			local hum = model:FindFirstChildOfClass("Humanoid")
			if model.Parent ~= entry.spawn or npcSpawn(model) ~= entry.spawn or hum and hum ~= entry.hum
				or entry.hum.Health ~= entry.hum.Health or entry.hum.Health > 0 or entry.hum.Health == -math.huge then return end
			-- v7510 moves the dead body under the ORIGINAL NPC wrapper, removes
			-- its Humanoid/root and creates "<name> Corpse" / ClickPart / unnamed ClickDetector.
			-- Capture once; never substitute a same-name corpse or a different NPC life.
			if not entry.body then
				local body = model:FindFirstChild(entry.name .. " Corpse")
				if body and body:IsA("Model") then entry.body = body end
			end
			if entry.body and (entry.body.Parent ~= model or model:FindFirstChild(entry.name .. " Corpse") ~= entry.body) then return end
			local root = entry.body and (entry.body:FindFirstChild("ClickPart") or entry.body:FindFirstChild("HumanoidRootPart")) or model:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") then return entry.hum, root end
			return
		end
		local spawn = model and model.Parent
		local spawns = Workspace:FindFirstChild("NPCSpawns")
		local regular = spawn and spawn.Parent == spawns and spawn.Name == "BossSpawns" and spawn:IsA("BasePart")
		local gyaku = gyakuRole(model) ~= nil
		if not (regular or gyaku or npcSpawn(model))
			or not model:IsA("Model") or model:FindFirstChild("AC") or Players:GetPlayerFromCharacter(model) or headLocked(model) then return end
		local hum, root = model:FindFirstChild("Humanoid"), model:FindFirstChild("HumanoidRootPart")
		if hum and hum:IsA("Humanoid") and root and root:IsA("BasePart")
			and not defeatedHumanoids[hum]
			and hum.Health == hum.Health and hum.Health > 0 and hum.Health < math.huge
			and hum:GetState() ~= Enum.HumanoidStateType.Dead
			and (model ~= target or lockAllows(model)) then return hum, root end
		return nil, nil
	end
	local function applyFacing()
		if api._survival.active or not activeFarm() or not target then releaseFacing(); return end
		local now = os.clock()
		if now >= nextFacingValidation then
			nextFacingValidation = now + 0.05
			if pollLock then pollLock() end
			if absorptionBlocked(now) then release(); cancelMove(); releaseFacing(); routeRequest = nil; return end
			local safe = allowed()
			if not safe then table.clear(combatProgress); releaseFacing(); return end
			local hum = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local _, bossRoot = bossParts(target)
			if moveFault or now < recoveryAt or character ~= player.Character
				or not living(hum) or not root or not bossRoot or not selected(target)
				or not equippedWeapon() or not equipmentStatus(now)
				or not validPoint(root.Position) or not validPoint(bossRoot.Position) then releaseFacing(); return end
			if safeZoneBlocked(target, now) then skipProtected(target, now); return end
			if facingHumanoid ~= hum then
				releaseFacing(); facingHumanoid, originalAutoRotate = hum, hum.AutoRotate
			end
			facingRoot, facingBossRoot = root, bossRoot
			hum.AutoRotate = false
			state.facingTarget = (bossRoot.Position - root.Position).Magnitude >= 0.001
		end
		local root, bossRoot = facingRoot, facingBossRoot
		if not root or not bossRoot or root.Parent == nil or bossRoot.Parent == nil then releaseFacing(); return end
		root.CFrame = facingFrame(root.Position, bossRoot, root.CFrame)
	end
	local function scan()
		syncSafeZones(); safeZoneAt(nil)
		table.clear(candidates)
		local spawns = Workspace:FindFirstChild("NPCSpawns")
		if spawns then
			for _, spawn in ipairs(spawns:GetChildren()) do
				if (spawn.Name == "BossSpawns" or spawn.Name == "GyakusatsuSpawn" or npcSpawns[spawn.Name]) and spawn:IsA("BasePart") then
					for _, model in ipairs(spawn:GetChildren()) do
						if bossParts(model) and kind(model) ~= "Corpse" then
							table.insert(candidates, model)
							if npcSpawn(model) then discoveredNPCs[model.Name] = true else discovered[bossName(model)] = true end
						end
					end
				end
			end
		end
		-- The giant visual rig may be a separate model. Only finite-health combat rigs qualify.
		for _, model in ipairs(Workspace:GetChildren()) do
			if model.Name == "Gyakusatsu" and bossParts(model) then
				table.insert(candidates, model); discovered.Gyakusatsu = true
			end
		end
		local spawn = encounterSpawn()
		local head = spawn and spawn:FindFirstChild("Gyakusatsu") or Workspace:FindFirstChild("Gyakusatsu")
		local live, pending = heartBarrier(spawn)
		state.gyakusatsuHearts, state.gyakusatsuPendingHearts = live, pending
		state.gyakusatsuPhase = live > 0 and "Hearts" or pending > 0 and "Waiting for hearts"
			or head and bossParts(head) and "Boss" or head and "Waiting for boss" or "Absent"
		if head or live > 0 or pending > 0 then discovered.Gyakusatsu = true end
		local names = {}
		for name in pairs(discovered) do table.insert(names, name) end
		table.sort(names)
		state.bossNames = names
		local npcNames = {}
		for name in pairs(discoveredNPCs) do table.insert(npcNames, name) end
		table.sort(npcNames); state.npcNames = npcNames
	end
	local function clearTarget()
		release()
		cancelMove()
		releaseFacing()
		if target and not farmLock and kind(target) ~= "Corpse" then
			local hum = target:FindFirstChild("Humanoid")
			if hum and hum:IsA("Humanoid") and hum.Health <= 0 and hum.Health > -math.huge then state.observedDeaths += 1 end
		end
		target, state.target, state.targetKind, approachDirection, targetSample, state.targetDistance, routeRequest, routeBlocked = nil, nil, nil, nil, nil, nil, nil, nil
	end
	local function releaseLock()
		if farmLock then for model in pairs(farmLock.members) do combatProgress[model] = nil end end
		clearTarget(); disconnectLinks(lockLinks)
		farmLock, state.lockedBoss, state.lockedNPC, state.lockId = nil, nil, nil, nil
	end
	skipProtected = function(model, now)
		local blocked, reason, zone = safeZoneBlocked(model, now)
		if not blocked then return false end
		state.safeZoneSkips += 1
		state.lastSafeZoneSkip = { target = targetLabel(model), kind = kind(model),
			lockId = farmLock and farmLock.id, at = now, reason = reason, zone = zone and zone:GetFullName() }
		-- Release ownership, not the living candidate or a death/removal record.
		if farmLock then releaseLock() else combatProgress[model] = nil; clearTarget() end
		nextTick, nextScan = 0, 0; state.reason = reason
		return true
	end
	local function observeMember(lock, model, role)
		if lock.members[model] then return lock.members[model] end
		local hum = model:FindFirstChild("Humanoid") or (role == "Head" and model:FindFirstChild("Statue"))
		if not hum or not hum:IsA("Humanoid") then return end
		local member = { model = model, hum = hum, role = role, slot = role == "Heart" and model.Name or nil,
			dead = false, removed = false, removedSince = nil, engaged = false, active = role ~= "Head" or hum.Name == "Humanoid" }
		lock.members[model] = member
		local function died()
			if farmLock ~= lock or member.dead or not member.active then return end
			member.dead = true; defeatedHumanoids[hum] = true
			if member.engaged then state.observedDeaths += 1 end -- Observation, never a credited kill.
			if lock.kind == "NPC" and member.engaged then
				state.npcDeaths += 1
				if options.npcFarm and options.absorbNPC == 1 and options.selectedNPCs[lock.name] then
					pendingCorpse = { model = model, hum = hum, spawn = lock.spawn, name = lock.name, at = os.clock(), attempts = 0 }
				end
				nextTick, nextScan = 0, 0 -- Do not retain the old combat/scan cadence after NPC death.
			end
			if target == model then clearTarget() end
		end
		member.died = died
		listen(lockLinks, hum.Died, died)
		listen(lockLinks, hum.HealthChanged, function(health)
			local root = model:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") then sampleCombatProgress(model, hum, root, os.clock()) end
			if health == health and health <= 0 and health > -math.huge then died() end
		end)
		listen(lockLinks, hum.StateChanged, function(_, setting) if setting == Enum.HumanoidStateType.Dead then died() end end)
		return member
	end
	local function syncEncounter(lock)
		-- Never rediscover a different spawn/head/heart after an identity disappears.
		local spawn = lock.spawn
		if spawn and spawn == encounterSpawn() then
			for _, name in ipairs(heartNames) do
				local model = lock.slots[name] or spawn:FindFirstChild(name)
				if model and model:IsA("Model") then
					lock.slots[name] = model; observeMember(lock, model, "Heart")
				end
			end
		end
		if not lock.head then
			local head = (not spawn or spawn == encounterSpawn()) and (spawn and spawn:FindFirstChild("Gyakusatsu") or Workspace:FindFirstChild("Gyakusatsu"))
			if head and gyakuRole(head) == "Head" then lock.head = head end
		end
		if lock.head then observeMember(lock, lock.head, "Head") end
	end
	local function pollRemovedHeart(lock, member, now)
		if member.role ~= "Heart" or member.dead or member.removed then return end
		local model, spawn, head = member.model, lock.spawn, lock.head
		local headMember = head and lock.members[head]
		-- v7510 destroys hearts before a final Health/Died packet may replicate.
		-- Retire this COMPONENT, never declare the boss/encounter dead. Mere
		-- reparenting, a missing root/Humanoid, or a replacement slot is not enough.
		local fullyRemoved = spawn and spawn == encounterSpawn() and head and headMember and not headMember.dead
			and gyakuRole(head) == "Head" and head:FindFirstChildOfClass("Humanoid") == headMember.hum
			and spawn:FindFirstChild(member.slot) == nil and model.Parent == nil
			and member.hum.Parent == nil and model:FindFirstChild("HumanoidRootPart") == nil
			and model:FindFirstChildOfClass("Humanoid") == nil
		if not fullyRemoved then member.removedSince = nil; return end
		member.removedSince = member.removedSince or now
		if now - member.removedSince < 0.25 then return end -- Reject an incomplete transient replication sample.
		member.removed = true
		state.gyakusatsuRemovedHearts += 1
		state.lastRemovedHeart = { lockId = lock.id, slot = member.slot, at = now }
		if target == model then clearTarget() end
	end
	local function pollRemovedBoss(lock, member, now)
		if lock.gyaku or member.dead or member.removed then return end
		local model, spawn, container = member.model, lock.spawn, lock.spawnContainer
		-- Ordinary NPCs can also be destroyed before the final death packet.
		-- Release a completely erased ORIGINAL rig, not a living/missing-root
		-- boss, and do not count deletion (or a same-name arrival) as a kill.
		-- BossSpawns names are duplicated: validate the captured part by identity.
		local fullyRemoved = container and container == Workspace:FindFirstChild("NPCSpawns")
			and spawn and spawn.Parent == container and (spawn.Name == "BossSpawns" or lock.kind == "NPC" and npcSpawns[spawn.Name]) and spawn:IsA("BasePart")
			and model.Parent == nil and member.hum.Parent == nil and #model:GetChildren() == 0
		if not fullyRemoved then member.removedSince = nil; return end
		member.removedSince = member.removedSince or now
		if now - member.removedSince < 0.25 then return end
		member.removed = true
		if lock.kind ~= "NPC" then
			state.removedBosses += 1
			state.lastRemovedBoss = { lockId = lock.id, boss = lock.name, at = now }
		end
	end
	local function acquireLock(model)
		lockSequence += 1
		local role = gyakuRole(model)
		local spawn
		if role then spawn = gyakuSpawn(model) or encounterSpawn() else spawn = model.Parent end
		local lock = { name = bossName(model), kind = kind(model), model = model, spawn = spawn, spawnContainer = not role and spawn and spawn.Parent or nil,
			head = role == "Head" and model or nil, slots = {}, members = {}, gyaku = role ~= nil, id = lockSequence }
		farmLock = lock; state.lockedBoss, state.lockedNPC, state.lockId = lock.kind == "Boss" and lock.name or nil, lock.kind == "NPC" and lock.name or nil, lock.id
		if lock.gyaku then syncEncounter(lock) else observeMember(lock, model) end
		local member = lock.members[model]
		if member then member.engaged = true end
	end
	pollLock = function()
		local lock = farmLock
		if not lock then return end
		if lock.gyaku then syncEncounter(lock) end
		for _, member in pairs(lock.members) do
			local hum = member.hum
			if member.role == "Head" and hum.Name == "Humanoid" then member.active = true end
			if not member.dead and member.active and ((hum.Health == hum.Health and hum.Health <= 0 and hum.Health > -math.huge)
				or hum:GetState() == Enum.HumanoidStateType.Dead) then member.died() end
			if lock.gyaku then pollRemovedHeart(lock, member, os.clock()) else pollRemovedBoss(lock, member, os.clock()) end
		end
		local complete = lock.gyaku and lock.head and lock.members[lock.head] or not lock.gyaku and lock.members[lock.model]
		if complete and (complete.dead or not lock.gyaku and complete.removed) then
			releaseLock(); nextScan = 0 -- The next allowed tick scans fresh lives, even with priority disabled.
		elseif lock.gyaku and target == lock.head and headLocked(target) then clearTarget() end -- Stage gating, never another encounter.
	end
	local function priorityRank(name)
		return table.find(options.bossPriority, name) or (#options.bossPriority + 1)
	end
	local function chooseTarget(root, now, within, aboveRank, bossOnly)
		local best, bestRank, choice, waiting, protected, unknown = math.huge, math.huge, nil, false, false, false
		local ranks = {}
		if options.bossPriorityEnabled and not within then
			for index, name in ipairs(options.bossPriority) do ranks[name] = index end
		end
		local models = within and within.members or candidates
		for key, entry in pairs(models) do
			local model = within and key or entry
			local member = within and entry
			local _, rootPart = bossParts(model)
			local category = kind(model)
			local rank = category == "NPC" and 1000000 or ranks[bossName(model)] or (options.bossPriorityEnabled and #options.bossPriority + 1 or 0)
			if rootPart and selected(model) and category ~= "Corpse" and (not bossOnly or category == "Boss") and (not aboveRank or validPoint(rootPart.Position))
				and (not aboveRank or rank < aboveRank) and (not member or not member.dead and not member.removed and lockAllows(model)) then
				local blocked, reason = safeZoneBlocked(model, now)
				if blocked then protected = true; unknown = unknown or reason == "Waiting for safe zone data"
				elseif not within and not aboveRank and (routeBackoff[model] or 0) > now then waiting = true
				else
					local distance = (rootPart.Position - root.Position).Magnitude
					if rank < bestRank or rank == bestRank and distance < best then choice, best, bestRank = model, distance, rank end
				end
			end
		end
		return choice, waiting, protected, unknown
	end
	local function preemptLock(root, now)
		if not activeFarm() or not farmLock or farmLock.kind ~= "NPC" and not options.bossPriorityEnabled then return end
		local old = farmLock
		local fromRank = priorityRank(old.name)
		local choice = chooseTarget(root, now, nil, old.kind ~= "NPC" and fromRank or nil, true)
		if not choice then return end
		if old.kind == "NPC" then state.npcPreemptions += 1 end
		pendingCorpse = nil
		local toBoss, toRank = bossName(choice), priorityRank(bossName(choice))
		-- Priority is an authorized release, NOT evidence that the old boss died.
		-- Tear down old input/Tween/facing/listeners before installing the new life.
		releaseLock(); target = choice; acquireLock(choice); state.target = targetLabel(choice)
		state.prioritySwitches += 1
		state.lastPrioritySwitch = { fromId = old.id, toId = farmLock.id, fromBoss = old.name, toBoss = toBoss,
			fromRank = fromRank, toRank = toRank, at = now }
	end
	local function resetCharacterWork()
		-- Character-owned work dies; boss identity and death listeners do not.
		api._trainer.token, api._trainer.completionToken = nil, nil; api:_updateTrainerBusy()
		api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
		state.trainerFinishMode = nil
		api._survival.active, api._survival.character, api._survival.healthySince = false, nil, nil
		state.survivalActive, state.survivalHealth, state.survivalSince = false, nil, nil
		release(); cancelMove(); releaseFacing(); clearCooldowns(); table.clear(routeBackoff)
		table.clear(combatProgress)
		approachDirection, targetSample, state.targetDistance, routeRequest, routeBlocked = nil, nil, nil, nil, nil
		table.clear(equipment); lastEquipmentKey = nil
		state.equipmentReady, state.equipmentPreparing, state.arataEquipped, state.maskEquipped = false, false, false, false
		state.cToggleSent = false
		nextEquip, nextInput, nextClick, nextSkill, nextArata, nextMask, nextTrainer, nextTick = 0, 0, 0, 0, 0, 0, 0, 0
		recoveryAt, recoveryLevel, lastBackoff, state.recoveryDelay = 0, 0, 0, 0; table.clear(displacementTimes)
	end
	local function awaitRespawn(expected, hum)
		if not alive() or character ~= expected then return end
		resetCharacterWork()
		-- Every requested farm survives respawn; an unresolved safety fault is
		-- NOT cleared here and still requires fresh route validation afterward.
		if farmRequested then
			respawnSource = respawnSource or { character = expected, humanoid = hum, fault = moveFault }
			state.respawnPending = true
		end
		state.reason = "Waiting for character"
	end
	refreshCharacter = function()
		local incoming = player.Character
		if incoming == removingCharacter then incoming = nil end
		if incoming ~= character then
			if character then awaitRespawn(character, characterHumanoid) end
			resetCharacterWork(); disconnectLinks(characterLinks); disconnectLinks(characterPartLinks)
			character, characterHumanoid = incoming, nil
			rebuildCollisionParts(incoming)
			if incoming then
				removingCharacter = nil
				listen(characterPartLinks, incoming.DescendantAdded, trackCollisionPart)
				listen(characterPartLinks, incoming.DescendantRemoving, untrackCollisionPart)
			end
		end
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		if hum ~= characterHumanoid then
			if characterHumanoid then awaitRespawn(character, characterHumanoid) end
			resetCharacterWork()
			disconnectLinks(characterLinks); characterHumanoid = hum
			if hum then
				local expected = character
				local function died()
					if characterHumanoid == hum then awaitRespawn(expected, hum) end
				end
				listen(characterLinks, hum.Died, function() retiredHumanoid = hum; died() end)
				listen(characterLinks, hum.HealthChanged, function(health)
					nextTick = 0
					if health <= 0 then died() end
				end)
				listen(characterLinks, hum.StateChanged, function(_, setting)
					if setting == Enum.HumanoidStateType.Dead then retiredHumanoid = hum; died() end
				end)
			end
		end
		if hum and not living(hum) then awaitRespawn(character, hum); return false end
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not living(hum) or not root or not root:IsA("BasePart") then return false end
		if respawnSource and farmRequested and (character ~= respawnSource.character or hum ~= respawnSource.humanoid or not moveFault)
			and (not moveFault or moveFault == respawnSource.fault) then
			if not moveFault then state.lastError = nil end
			respawnSource, state.respawnPending = nil, false; state.respawnResumes += 1
			resetCharacterWork()
		elseif not respawnSource then state.respawnPending = false end
		return true
	end
	local function blocked(x, y)
		local playerGui = player:FindFirstChildOfClass("PlayerGui")
		if not playerGui then return true end
		for _, container in ipairs({ playerGui, CoreGui }) do
			for _, gui in ipairs(container:GetGuiObjectsAtPosition(x, y)) do
				if gui.Visible and (gui.Active or gui:IsA("GuiButton") or gui:IsA("TextBox")) then return true end
			end
		end
		return false
	end
	local function aimPoint(root)
		local camera = Workspace.CurrentCamera
		if not camera then return end
		-- Native mouse coordinates include Roblox's GUI inset, unlike viewport coordinates.
		local point, visible = camera:WorldToScreenPoint(root.Position)
		if not visible or point.Z <= 0 then return end
		local params = RaycastParams.new()
		params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, { character }
		local hit = Workspace:Raycast(camera.CFrame.Position, root.Position - camera.CFrame.Position, params)
		if hit and not hit.Instance:IsDescendantOf(target) then
			local visual = targetVisual(target)
			if not visual or not hit.Instance:IsDescendantOf(visual) then return end
		end
		local cursor = Input:GetMouseLocation()
		local x, y = cursor.X, cursor.Y
		if activeFarm() then x, y = point.X, point.Y end
		local inset = GuiService:GetGuiInset()
		if x < 0 or y < inset.Y or x >= camera.ViewportSize.X or y >= camera.ViewportSize.Y + inset.Y or blocked(x, y) then return end
		return x, y
	end
	function api:SetOption(key, setting)
		if key == "skills" then
			if type(setting) ~= "table" then return false, "skills must be a table" end
			for _, name in ipairs(skillKeys) do options.skills[name] = setting[name] == true end
		elseif key == "selectedBosses" or key == "selectedNPCs" then
			if type(setting) ~= "table" then return false, key .. " must be a list or set" end
			local selected = {}
			for name, entry in pairs(setting) do
				if type(entry) == "string" then selected[entry] = true
				elseif type(name) == "string" and entry == true then selected[name] = true end
			end
			options[key] = selected
		elseif key == "bossPriority" then
			if type(setting) ~= "table" then return false, "bossPriority must be an ordered list" end
			local order, seen = {}, {}
			local count = 0
			for index in pairs(setting) do
				if type(index) ~= "number" or index % 1 ~= 0 or index < 1 or index > #setting then return false, "dense ordered list required" end
				count += 1
			end
			if count ~= #setting then return false, "dense ordered list required" end
			for _, name in ipairs(setting) do
				if type(name) ~= "string" or name == "" or seen[name] then return false, "unique boss names required" end
				seen[name] = true; table.insert(order, name)
			end
			options.bossPriority = order
		elseif key == "selectedTrainer" then
			if type(setting) ~= "string" or setting == "" or #setting > 160 then return false, "selectedTrainer must be a name" end
			options.selectedTrainer = setting
		elseif key == "cMode" then
			if setting ~= "Use" and setting ~= "Toggle" then return false, "cMode must be Use or Toggle" end
			options.cMode = setting
		elseif key == "farmMethod" then
			if setting ~= "Above" and setting ~= "Behind" and setting ~= "Down" then return false, "farmMethod must be Above, Behind or Down" end
			options.farmMethod = setting
		elseif key == "absorbNPC" then
			if setting ~= 0 and setting ~= 1 then return false, "absorbNPC must be 0 or 1" end
			options.absorbNPC = setting
		elseif key == "weaponStage" then
			if type(setting) ~= "number" or setting ~= setting or setting < 1 or setting > 9 or setting % 1 ~= 0 then
				return false, "weaponStage must be an integer from 1 to 9"
			end
			options.weaponStage = setting
		elseif key == "distance" or key == "moveSpeed" or key == "clickInterval" or key == "skillInterval" then
			if type(setting) ~= "number" or setting ~= setting or math.abs(setting) == math.huge then return false, "finite number required" end
			local ranges = { distance = { 2, 40 }, moveSpeed = { 20, 400 }, clickInterval = { 0.02, 1 }, skillInterval = { 0.15, 3 } }
			options[key] = math.clamp(setting, ranges[key][1], ranges[key][2])
		elseif type(options[key]) == "boolean" and type(setting) == "boolean" then options[key] = setting
		else return false, "Unknown option or invalid value" end
		if key ~= "autoTrainer" and key ~= "selectedTrainer" and key ~= "godMode" then
			table.clear(combatProgress)
			release()
		end
		if key == "godMode" and not setting and api._survival.active then api:_resetSurvival(true, false) end
		if key == "autoTrainer" then
			api._trainer.token, api._trainer.completionToken, nextTrainer = nil, nil, 0
			api:_updateTrainerBusy()
			if setting then
				state.trainerStatus = "Starting trainer"
			else
				api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
				state.trainerFinishMode = nil
				state.trainerStatus, state.trainerTarget, state.trainerProgress, state.trainerResponse = "Idle", nil, nil, nil
			end
		end
		if (key == "farm" or key == "npcFarm") and setting == true then
			options.autoClick = true; nextClick = 0
		end
		if key == "farm" or key == "npcFarm" then
			if key == "farm" and not options.npcFarm or not activeFarm() then
				if moveFault then moveFault = nil; state.lastError = nil end
				recoveryAt, recoveryLevel, lastBackoff, state.recoveryDelay = 0, 0, 0, 0; table.clear(displacementTimes)
			end
			farmRequested = activeFarm()
			if not farmRequested then respawnSource, state.respawnPending = nil, false end
		end
		if farmLock and (farmLock.kind == "Boss" and (key == "farm" and not setting or key == "selectedBosses" and not options.selectedBosses[farmLock.name])
			or farmLock.kind == "NPC" and (key == "npcFarm" and not setting or key == "selectedNPCs" and not options.selectedNPCs[farmLock.name])) then releaseLock() end
		if pendingCorpse and (not options.npcFarm or options.absorbNPC == 0 or not options.selectedNPCs[pendingCorpse.name]) then
			if target == pendingCorpse.model then clearTarget() end
			pendingCorpse = nil
		end
		if key == "autoArata" then nextArata, equipment.arataSince = 0, nil end
		if key == "autoMask" then nextMask, equipment.maskSince = 0, nil end
		if key == "selectedTrainer" then
			api._trainer.token, api._trainer.completionToken = nil, nil
			api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
			state.trainerFinishMode = nil
			api:_updateTrainerBusy()
			nextTrainer, state.trainerResponse = 0, nil
		end
		if key == "autoArata" or key == "autoMask" then
			-- Do not expose a pre-option confirmation in an immediate API snapshot.
			state.equipmentReady, state.equipmentPreparing = false, false
		end
		if (key == "autoArata" or key == "autoMask") and setting then
			cancelMove(); releaseFacing(); routeRequest = nil
		end
		if key == "farm" or key == "npcFarm" or key == "selectedBosses" or key == "selectedNPCs" or key == "distance" or key == "moveSpeed" or key == "autoClick" or key == "farmMethod" then
			cancelMove(key == "farmMethod" and activeFarm() and (movement ~= nil or hover ~= nil))
			routeRequest, routeBlocked = nil, nil; table.clear(routeBackoff)
			if key == "farm" or key == "npcFarm" or key == "selectedBosses" or key == "selectedNPCs" then releaseFacing(); nextScan = 0 end
		end
		return true
	end
	-- Compatibility only: hub visibility must not own automation or movement.
	function api:SetMenuOpen(_open) end
	function api:SetStartupCombatHeld(setting)
		startupCombatHeld = setting == true
		if startupCombatHeld then release(); cancelMove(); releaseFacing(); table.clear(combatProgress) end
	end
	-- Explicit diagnostic/observer lock, independent of the displayed hub.
	function api:SetSuspended(setting)
		suspended = setting == true
		if suspended then table.clear(combatProgress) end
		if suspended and absorption.pending then absorption.pending.readySince = nil end
		if suspended then
			api._trainer.token, api._trainer.completionToken = nil, nil
			api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
			state.trainerFinishMode = nil
			api:_updateTrainerBusy()
			if api._survival.active then api:_resetSurvival(false, false) end
			release(); cancelMove(); releaseFacing(); routeRequest = nil
		end
	end
	function api:GetStatus()
		local copy = table.clone(state)
		copy.startupCombatHeld = startupCombatHeld
		copy.skillAttemptsByKey = table.clone(state.skillAttemptsByKey)
		copy.lastPrioritySwitch = state.lastPrioritySwitch and table.clone(state.lastPrioritySwitch)
		copy.lastRemovedHeart = state.lastRemovedHeart and table.clone(state.lastRemovedHeart)
		copy.lastRemovedBoss = state.lastRemovedBoss and table.clone(state.lastRemovedBoss)
		copy.lastSafetyPause = state.lastSafetyPause and table.clone(state.lastSafetyPause)
		copy.lastSafetyResume = state.lastSafetyResume and table.clone(state.lastSafetyResume)
		copy.lastSafeZoneSkip = state.lastSafeZoneSkip and table.clone(state.lastSafeZoneSkip)
		local progress = target and combatProgress[target]
		copy.targetCombatProgress = progress ~= nil and progress.damageAt ~= nil and os.clock() - progress.damageAt < 3
			and progress.character == player.Character and progress.playerHum == player.Character:FindFirstChildOfClass("Humanoid")
			and target.Parent == progress.parent and target:FindFirstChild("Humanoid") == progress.hum
			and target:FindFirstChild("HumanoidRootPart") == progress.root and living(progress.playerHum)
			and activeFarm() and allowed() and absorption.pending == nil
		copy.safetyPaused, copy.safetyKind = moveFault ~= nil, moveFault and moveFault.kind
		local weapon = equippedWeapon()
		copy.cToggleSent, copy.cWeaponAvailable = weapon ~= nil and cToggles[character] == true, weapon ~= nil
		copy.bossNames, copy.allyPending = table.clone(state.bossNames), ally.pending ~= nil
		copy.pendingNativeReleases = 0
		for _ in pairs(nativeReleases) do copy.pendingNativeReleases += 1 end
		copy.clickHolding = clickHeld ~= nil
		copy.farmMethod = options.farmMethod
		copy.weaponStage = options.weaponStage
		copy.absorbNPC, copy.npcFarm = options.absorbNPC, options.npcFarm
		local interaction = absorption.pending
		copy.absorptionPending = interaction ~= nil
		copy.absorptionPhase = interaction and interaction.phase or "Idle"
		copy.absorptionBusySeen = interaction and interaction.busySeen == true or false
		copy.absorptionElapsed = interaction and math.max(0, os.clock() - interaction.at) or 0
		copy.targetKind = target and kind(target) or nil
		copy.npcNames = table.clone(state.npcNames)
		copy.recoveryRemaining = activeFarm() and math.max(0, recoveryAt - os.clock()) or 0
		return copy
	end
	function api:GetBossNames() return table.clone(state.bossNames) end
	function api:GetNPCNames() return table.clone(state.npcNames) end
	function api:GetTrainerNames()
		local folder = player:FindFirstChild("PlayerFolder")
		local _, order = trainerOrder(folder)
		local names, seen = { "Auto" }, { Auto = true }
		for _, name in ipairs(order) do seen[name] = true; table.insert(names, name) end
		local trainers = folder and folder:FindFirstChild("Trainers")
		if trainers then
			local additions = {}
			for _, entry in ipairs(trainers:GetChildren()) do if not seen[entry.Name] then table.insert(additions, entry.Name) end end
			table.sort(additions); for _, name in ipairs(additions) do table.insert(names, name) end
		end
		return names
	end
	function api:GetTargetIdentity()
		local member = farmLock and farmLock.members[target]
		return { model = target, humanoid = member and member.hum, boss = farmLock and farmLock.model,
			head = farmLock and farmLock.head, spawn = farmLock and farmLock.spawn,
			spawnContainer = farmLock and farmLock.spawnContainer, id = farmLock and farmLock.id }
	end
	function api:Stop()
		if stopped then return end
		stopped, state.running, state.reason = true, false, "Stopped"
		api._trainer.token, api._trainer.completionToken = nil, nil
		api._trainer.code, api._trainer.codeCharacter, api._trainer.finishMode = nil, nil, nil
		state.trainerFinishMode = nil
		api:_updateTrainerBusy()
		if api._survival.active then api:_resetSurvival(false, false) end
		state.equipmentPreparing = false
		farmRequested, respawnSource, state.respawnPending = false, nil, false
		moveFault, recoveryAt, state.recoveryDelay = nil, 0, 0
		pendingCorpse = nil
		release()
		flushNativeReleases()
		cancelMove()
		releaseFacing()
		RunService:UnbindFromRenderStep(renderName)
		routeRequest = nil
		releaseLock()
		for _, connection in ipairs(connections) do connection:Disconnect() end
		clearCooldowns()
		disconnectLinks(characterLinks); disconnectLinks(characterPartLinks)
		table.clear(collisionParts)
		table.clear(combatProgress); table.clear(zoneParts); zoneContainer = nil
		table.clear(connections)
		if lifecycle.roGhoulController == self then lifecycle.roGhoulController = nil end
	end
	local function addAlly(folder, now)
		if not options.autoAlly or ally.pending or now < ally.nextAt then return end
		local allied = folder:FindFirstChild("Allied")
		local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
		local group = remotes and remotes:FindFirstChild("Ally")
		local remote = group and group:FindFirstChild("ToggleAlly")
		if not allied or not remote or not remote:IsA("RemoteFunction") then return end
		for _, other in ipairs(Players:GetPlayers()) do
			if other ~= player and not allied:FindFirstChild(other.Name) and not ally.attempted[other.UserId] then
				local token, expectedCharacter = {}, character
				ally.pending, ally.nextAt = token, now + 1
				task.spawn(function()
					if not alive() or not options.autoAlly or not allowed() or player.Character ~= expectedCharacter
						or other.Parent ~= Players or allied:FindFirstChild(other.Name) then
						if ally.pending == token then ally.pending = nil end
						return
					end
					ally.attempted[other.UserId] = true
					state.allyAttempts += 1
					local ok, err = pcall(function() remote:InvokeServer(other.Name) end)
					-- Only bookkeeping after this yield; a stopped/reloaded owner never acts again.
					if ally.pending == token then ally.pending = nil; ally.nextAt = os.clock() + 1 end
					if alive() and not ok then state.lastError = "Ally outcome uncertain: " .. tostring(err) end
				end)
				return
			end
		end
	end
	local function step(now)
		pollLock() -- Death/removal bookkeeping also runs while dead, equipping, suspended or safety-paused.
		if pendingCorpse and (now - pendingCorpse.at > 3 or not selected(pendingCorpse.model)
			or pendingCorpse.model.Parent ~= pendingCorpse.spawn or pendingCorpse.body and pendingCorpse.body.Parent ~= pendingCorpse.model) then
			if target == pendingCorpse.model then clearTarget() end
			pendingCorpse = nil
		end
		local characterReady = refreshCharacter()
		local waitingAbsorption = absorptionBlocked(now)
		if now >= nextScan then
			scan()
			nextScan = now + (activeFarm() and (target and 1 or 0.2) or 2)
		end
		local safe, reason = allowed()
		state.inputMode = (activeFarm() or options.autoClick) and (gameInput() and "Game action" or "Unavailable")
			or options.autoTrainer and "Trainer remote" or "Native"
		state.reason, state.allyPending = reason, ally.pending ~= nil
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local folder = player:FindFirstChild("PlayerFolder")
		if not characterReady or not folder then
			release(); cancelMove(); state.reason = "Waiting for character"; return
		end
		-- Online v7510 evidence: moving away while the absorption owns CanAct
		-- can produce the server warning/death even with zero subsequent attacks.
		-- Retire every movement/facing/input owner BEFORE acquisition, gear or route work.
		if waitingAbsorption then
			release(); cancelMove(); releaseFacing(); routeRequest, targetSample = nil, nil
			state.canAct = value(folder, "CanAct") == true
			state.reason = "Cannot act"; return
		end
		syncCooldowns(folder)
		local canAct = value(folder, "CanAct") == true
		state.canAct = canAct
		local survivalActive = api:_updateSurvival(now, hum)
		if not safe and not survivalActive then table.clear(combatProgress); release(); cancelMove(); return end
		if safe then api:_stepCToggle(now, folder, root, canAct, survivalActive) end
		if moveFault and now < recoveryAt and not survivalActive then
			release(); cancelMove(); releaseFacing(); state.reason = "Safety pause"; return
		end
		if safe then stepTrainer(now, folder) end
		if target and not survivalActive then skipProtected(target, now) end
		-- Healthy/allowed farm only. Death and suspension retain identity; the
		-- first ready tick may preempt before recovery/gear preparation/travel.
		if not survivalActive then preemptLock(root, now) end
		if not survivalActive and target and kind(target) == "Corpse" and options.farm then
			local boss = chooseTarget(root, now, nil, nil, true)
			if boss then
				clearTarget(); pendingCorpse = nil; target = boss; acquireLock(boss); state.npcPreemptions += 1
			end
		end
		if now < recoveryAt and not survivalActive then state.reason = "Recovering position"; return end
		addAlly(folder, now)
		local prepared, equipmentReason, needsArata, needsMask = equipmentStatus(now)
		if activeFarm() and not prepared and not survivalActive then
			-- Reserve only the preparation phase. No M1/skills may keep CanAct
			-- busy while gear is being restored; combat cadence is unchanged later.
			releaseClick(); cancelMove(); releaseFacing(); routeRequest, targetSample = nil, nil
			if held and held ~= 0x30 and held ~= 0x4D then releaseKey() end
			state.reason = equipmentReason
		end
		if not survivalActive and canAct and not held and now >= nextInput and value(folder, "CanToggleWep") == true then
			local arataDue, maskDue = needsArata and now >= nextArata, needsMask and now >= nextMask
			-- Fair turns: an unaccepted Arata request cannot starve the mask.
			if arataDue and (not maskDue or lastEquipmentKey ~= "Arata") then
				if pulse(0x30, now) then state.arataAttempts += 1; nextArata = now + 2; lastEquipmentKey = "Arata" end
			elseif maskDue then
				if pulse(0x4D, now) then state.maskAttempts += 1; nextMask = now + 2; lastEquipmentKey = "Mask" end
			end
		end
		if activeFarm() and not prepared and not survivalActive then return end
		if startupCombatHeld and not survivalActive then release(); cancelMove(); releaseFacing(); state.reason = "Waiting for manual start"; return end
		if activeFarm() and not survivalActive and not equippedWeapon() then
			local current = value(folder, "CurrentWep")
			if canAct and (current == "" or current == "None") and value(folder, "CanToggleWep") == true
				and now >= nextEquip and pulse(0x30 + options.weaponStage, now) then
				state.equipAttempts += 1; nextEquip = now + 2
			end
			cancelMove(); state.reason = "Equipping weapon"; return
		end
		if not activeFarm() and not farmLock and target and (not bossParts(target) or not selected(target) or (routeBackoff[target] or 0) > now) then clearTarget() end
		if target and activeFarm() and not farmLock and kind(target) ~= "Corpse" then
			if bossParts(target) and selected(target) then acquireLock(target) else clearTarget() end
		end
		if not target then
			local waitingForRoute, protected, unknown
			if farmLock and farmLock.gyaku then
				target, waitingForRoute, protected, unknown = chooseTarget(root, now, farmLock)
				if not target and protected then
					releaseLock(); target, waitingForRoute, protected, unknown = chooseTarget(root, now)
				end
			elseif farmLock then target = farmLock.model
			else target, waitingForRoute, protected, unknown = chooseTarget(root, now) end
			if pendingCorpse and not farmLock then
				if target and kind(target) == "Boss" then pendingCorpse = nil
				elseif now - pendingCorpse.at <= 3 and selected(pendingCorpse.model) then target = pendingCorpse.model
				else pendingCorpse = nil end
			end
			if target and activeFarm() and not farmLock and kind(target) ~= "Corpse" then acquireLock(target) end
			if target and farmLock and farmLock.members[target] then farmLock.members[target].engaged = true end
			if not target and waitingForRoute then state.reason = "Unsafe route"; return end
			if not target and protected then
				state.reason = unknown and "Waiting for safe zone data" or "Target in safe zone"; return
			end
		end
		state.target = targetLabel(target)
		if not target then
			state.reason = farmLock and "Waiting for Gyakusatsu" or options.farm and options.selectedBosses["Gyakusatsu"] and state.gyakusatsuPhase ~= "Absent" and "Waiting for Gyakusatsu"
				or options.npcFarm and (next(options.selectedNPCs) and "No selected NPC alive" or "No NPCs selected")
				or next(options.selectedBosses) and "No selected boss alive" or "No bosses selected"
			return
		end
		local _, bossRoot = bossParts(target)
		if not bossRoot then
			release(); cancelMove(); releaseFacing(); routeRequest, targetSample = nil, nil
			state.reason = kind(target) == "Corpse" and "Waiting for corpse" or farmLock and farmLock.gyaku and "Waiting for Gyakusatsu" or "Waiting for locked boss"; return
		end
		if skipProtected(target, now) then return end
		if farmLock and (routeBackoff[target] or 0) > now then release(); cancelMove(); state.reason = "Unsafe route"; return end
		local targetVelocity, dashed = Vector3.zero, false
		if targetSample and targetSample.root == bossRoot then
			local elapsed = now - targetSample.time
			local shift = bossRoot.Position - targetSample.position
			dashed = shift.Magnitude > 10
			if elapsed > 0 and elapsed < 0.5 and not dashed then
				local velocity = shift / elapsed
				if velocity.Magnitude <= 120 then targetVelocity = velocity end
			end
		end
		targetSample = { root = bossRoot, position = bossRoot.Position, time = now }
		state.targetDistance = (bossRoot.Position - root.Position).Magnitude
		if activeFarm() then
			local attackRange = options.autoClick and 6 or options.distance + 2
			local emergency = api._survival.active
			-- Every farm method is a controlled no-collision flight. Behind keeps
			-- its rear offset, but never searches for floor support or a walk route.
			local floating = true
			local look = bossRoot.CFrame.LookVector
			local horizontal = Vector3.new(look.X, 0, look.Z)
			if horizontal.Magnitude < 0.01 then horizontal = Vector3.new(0, 0, -1) end
			approachDirection = horizontal.Unit
			-- Conservative melee envelope: a large display distance must not strand AutoClick out of range.
			local spacing = emergency and 24 or (options.autoClick and math.min(options.distance, 4) or options.distance)
			local lead = Vector3.new(targetVelocity.X, 0, targetVelocity.Z) * 0.08
			if lead.Magnitude > 4 then lead = lead.Unit * 4 end
			local desired
			if emergency then
				local away = Vector3.new(root.Position.X - bossRoot.Position.X, 0, root.Position.Z - bossRoot.Position.Z)
				if away.Magnitude < 0.01 then away = -approachDirection end
				desired = bossRoot.Position + away.Unit * spacing + Vector3.new(0, 36, 0)
			else
				local offset = options.farmMethod == "Above" and Vector3.new(0, spacing, 0)
					or options.farmMethod == "Down" and Vector3.new(0, -spacing, 0) or -approachDirection * spacing
				desired = bossRoot.Position + lead + offset
			end
			local owner = movement or hover
			local projected = owner and (floating and desired or Vector3.new(desired.X, owner.goal.Y, desired.Z))
			local changed = not owner or (projected - owner.goal).Magnitude > (state.targetDistance <= attackRange + 2 and 0.35 or 1.5)
			if (now >= nextMove or dashed) and changed then
				local position, routeError, route, navigationGoal = approachRoute(root.Position, desired, root, hum, bossRoot, spacing, floating)
				local navigationState, navigationError
				if not position and not floating and navigationGoal then
					route, navigationState, navigationError = navigationRoute(root.Position, navigationGoal, root, hum, target)
					-- Preserve the geometric rejection instead of disguising it as
					-- random NoPath. Only a supported endpoint reaches Walk planning.
					if navigationError then routeError = (routeError or "Небезопасный маршрут") .. "; " .. navigationError end
					if route then position = route.goal end
				end
				if not position then
					release()
					if not (movement or hover) or dashed or floating then cancelMove() end
					nextMove = now + 0.1
					routeBlocked = navigationState or "Unsafe route"
					state.reason, state.lastError = routeBlocked, routeError
					if not movement and routeBlocked == "Unsafe route" and state.targetDistance > attackRange then routeBackoff[target] = now + 2 end
					if moveFault then
						-- Keep M1, skills and facing gated while async planning or
						-- unsafe data persists. Never replay the cancelled owner.
						releaseFacing(); state.reason = "Safety pause"
						if navigationState ~= "Planning route" then
							state.safetyRetries += 1; deferSafetyRetry(now)
						end
						return
					end
				else
				if moveFault then
					state.safetyResumes += 1
					state.lastSafetyResume = { kind = moveFault.kind, at = now, lockId = farmLock and farmLock.id,
						target = targetLabel(target) }
					moveFault, state.lastError, recoveryAt, state.recoveryDelay = nil, nil, 0, 0
				end
				local remaining = route and route.length or (position - root.Position).Magnitude
				routeBlocked, routeRequest = nil, nil
				if remaining > (floating and 0.05 or 1.5) then
				if owner and not dashed and (position - owner.goal).Magnitude <= (state.targetDistance <= attackRange + 2 and 0.35 or 1.5) then
					-- Rejected nominal Behind points must not continually restart
					-- the same already-validated alternate landing/Tween.
					nextMove = now + 0.1
				else
					local replanning = movement ~= nil or hover ~= nil
					cancelMove(true)
					local travelSpeed = emergency and math.max(options.moveSpeed, 260) or options.moveSpeed
					local duration = math.max(1 / 60, remaining / travelSpeed)
					local driver = Instance.new("Vector3Value"); driver.Value = root.Position
					local driverGoal = route and root.Position + Vector3.new(route.length, 0, 0) or position
					-- Assign ownership before Create/Play: even a construction error must destroy the driver.
					movement = { driver = driver, root = root, started = now, duration = duration, origin = root.Position,
						goal = position, driverGoal = driverGoal, lastApplied = root.Position, travelled = 0,
						target = target, targetParent = target.Parent, bossRoot = bossRoot, route = route, floating = floating }
					local owner = movement
					owner.tween = TweenService:Create(driver, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Value = driverGoal })
					owner.completed = owner.tween.Completed:Connect(function(playback)
						if movement ~= owner then return end
						local ok, err = pcall(function()
							if playback == Enum.PlaybackState.Completed then owner.finished = true; applyMove() else cancelMove() end
						end)
						if not ok then api:Stop(); state.lastError = tostring(err); state.reason = "Stopped on error" end
					end)
					noCollision(); owner.tween:Play(); state.tweenStarts += 1; state.moving = true; nextMove = now + 0.1
					if replanning then state.pursuitReplans += 1 end
					state.lastError = nil
				end
				elseif floating then
					if not movement and not hover then
						hover = { root = root, goal = position, lastApplied = root.Position, travelled = 0,
							target = target, targetParent = target.Parent, bossRoot = bossRoot, floating = true }
						state.holdingPosition = true; noCollision()
					end
				elseif movement or hover then cancelMove() end
				end
			end
			if api._survival.active then
				state.reason = routeBlocked or (api._survival.healthySince and "God Mode recovery" or "God Mode retreat")
				return
			end
			local futureDistance = (bossRoot.Position + targetVelocity * 0.08 - root.Position).Magnitude
			if state.targetDistance > attackRange or futureDistance > attackRange then
				state.reason = routeBlocked or (kind(target) == "Corpse" and "Moving to corpse" or kind(target) == "NPC" and "Moving to NPC" or "Moving to boss"); return
			end
		end
		if kind(target) == "Corpse" then
			release()
			if waitingAbsorption then state.reason = "Cannot act"; return end
			local entry = pendingCorpse
			if not entry or now - entry.at > 3 or entry.attempts >= 1 then clearTarget(); pendingCorpse = nil; return end
			local detector = (entry.body or target):FindFirstChildWhichIsA("ClickDetector", true)
			local part = detector and detector.Parent
			if not detector or not part or not part:IsA("BasePart") or not validPoint(part.Position) then state.reason = "Waiting for corpse"; return end
			local maximum = detector.MaxActivationDistance
			if type(maximum) ~= "number" or maximum <= 0 or maximum ~= maximum or maximum == math.huge
				or (part.Position - root.Position).Magnitude > math.min(6, maximum) then state.reason = "Moving to corpse"; return end
			if not canAct then state.reason = "Cannot act"; return end
			cancelMove(); releaseFacing()
			absorption.pending = { character = character, hum = hum, folder = folder, canAct = folder:FindFirstChild("CanAct"),
				part = part, detector = detector, at = now, phase = "Waiting for interaction removal", busySeen = false }
			entry.attempts += 1; state.absorbAttempts += 1
			fireclickdetector(detector, (part.Position - root.Position).Magnitude, "mouseclick")
			-- Dispatch is not a reward acknowledgment. Retire only this already-dead
			-- life and its owners. The sent ledger holds both flight and combat until idle.
			clearTarget(); pendingCorpse = nil
			nextTick, nextScan = 0, 0 -- Observe the sent interaction on the very next Heartbeat.
			state.reason = "Absorbing NPC"; return
		end
		local direct = activeFarm() and gameInput() ~= nil
		if activeFarm() and options.autoClick and not direct then
			releaseClick(); state.reason = "Waiting for game input"; return
		end
		-- ClientControl v7510 sends skill keys regardless of CanAct (it only
		-- gates dash). Fast M1 must not starve these independent requests or
		-- prematurely release their key. The game still decides acceptance.
		if not canAct and not direct then releaseKey(); state.reason = "Cannot act"; return end
		local x, y
		if direct then
			local params = RaycastParams.new()
			params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, { character }
			local hit = Workspace:Raycast(root.Position, bossRoot.Position - root.Position, params)
			local visual = targetVisual(target)
			-- Down explicitly farms through the ordinary floor immediately above
			-- the held root. Keep unrelated walls/players and named hazards blocked.
			local underFloor = options.farmMethod == "Down" and hover and hit and not unsafePart(hit.Instance)
				and hit.Instance:IsA("BasePart") and hit.Instance.Anchored
				and math.abs((bossRoot.Position - root.Position).Unit.Y) > 0.9
				and hit.Normal and math.abs(hit.Normal.Y) > 0.65
			if hit and not underFloor and not hit.Instance:IsDescendantOf(target) and (not visual or not hit.Instance:IsDescendantOf(visual)) then
				state.reason = "Target not visible or cursor blocked"; return
			end
		else
			if not isrbxactive() then state.reason = "Roblox unfocused"; return end
			x, y = aimPoint(bossRoot)
			if not x then state.reason = "Target not visible or cursor blocked"; return end
		end
		if activeFarm() and not direct then
			if Input.MouseBehavior == Enum.MouseBehavior.LockCenter then state.reason = "Native aim locked"; return end
			mousemoveabs(x, y)
		end
		if not held and now >= nextInput and now >= nextSkill then
			for offset = 1, #skillKeys do
				local index = (skillIndex + offset - 1) % #skillKeys + 1
				local key = skillKeys[index]
				local weapon = key == "C" and equippedWeapon() or nil
				local once = key == "C" and options.cMode == "Toggle"
				if options.skills[key] and ready(folder, cooldowns[key], now)
					and (not once or (weapon and cToggles[character] ~= true)) then
					-- Consume before dispatch: an input error/unknown acknowledgment must not toggle twice.
					if once then cToggles[character] = true; state.cToggleSent = true end
					if not pulse(keycodes[key], now, bossRoot.Position) then return end
					state.skillAttempts += 1; state.skillAttemptsByKey[key] += 1; state.lastSkillKey = key
					nextSkill, skillIndex = now + options.skillInterval, index
					break
				end
			end
		end
	end
	local function gameClick(now)
		if not options.autoClick then if clickHeld then releaseClick() end; return end
		if not clickHeld and now < nextClick then return end
		pollLock()
		if api._survival.active or startupCombatHeld or absorptionBlocked(now) or not alive()
			or suspended or GuiService.MenuIsOpen or Input:GetFocusedTextBox() or moveFault or now < recoveryAt then releaseClick(); return end
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local folder = player:FindFirstChild("PlayerFolder")
		if character ~= player.Character or hum ~= characterHumanoid or not living(hum)
			or not root or not root:IsA("BasePart") or not folder then releaseClick(); return end
		if not gameInput() then
			releaseClick(); state.inputMode, state.reason = "Unavailable", "Waiting for game input"; return
		end
		if not allowed() then releaseClick(); return end
		if not equippedWeapon() then
			releaseClick(); if not activeFarm() then state.reason = "Equipping weapon" end; return
		end
		local prepared, equipmentReason = equipmentStatus(now)
		if not prepared then releaseClick(); state.reason = equipmentReason; return end
		state.inputMode = "Game action"
		if not activeFarm() then
			-- Aim forward from the current character. No selected boss, screen
			-- projection, mouse hover/focus or ordinary CanAct gate is needed.
			-- The sent-absorption ledger above still owns its global combat hold.
			state.reason = "Active"
			click(now); return
		end
		if target and kind(target) == "Corpse" then releaseClick(); return end
		local _, bossRoot = bossParts(target)
		if not target or not bossRoot or not selected(target) or not lockAllows(target)
			or (routeBackoff[target] or 0) > now then releaseClick(); return end
		if skipProtected(target, now) then return end
		-- Also runs while approaching or CanAct is false during a skill.
		-- The game decides whether the attempt actually hits.
		click(now, bossRoot.Position)
	end
	for key, setting in pairs(initial or {}) do
		local ok, err = api:SetOption(key, setting)
		assert(ok, tostring(err) .. ": " .. tostring(key))
	end
	if activeFarm() then options.autoClick = true end
	scan(); nextScan = os.clock() + 0.2
	lifecycle.roGhoulController = api
	lifecycle.onCleanup(function() api:Stop() end)
	local function connect(signal, callback)
		local connection = lifecycle.connect(signal, callback)
		if connection then table.insert(connections, connection) end
	end
	connect(player.Backpack.DescendantAdded, function(obj) api:_captureTrainerCode(obj) end)
	connect(player.ChildAdded, function(child)
		if not child:IsA("Backpack") then return end
		connect(child.DescendantAdded, function(obj) api:_captureTrainerCode(obj) end)
		for _, obj in ipairs(child:GetDescendants()) do api:_captureTrainerCode(obj) end
	end)
	connect(player.CharacterRemoving, function(removed)
		removed = removed or character
		if removed ~= character then return end
		awaitRespawn(removed, characterHumanoid); disconnectLinks(characterLinks); disconnectLinks(characterPartLinks)
		rebuildCollisionParts(nil)
		removingCharacter, character, characterHumanoid = removed, nil, nil
	end)
	connect(player.CharacterAdded, function() refreshCharacter() end)
	refreshCharacter()
	for _, obj in ipairs(player.Backpack:GetDescendants()) do api:_captureTrainerCode(obj) end
	local function isSpawnObject(part)
		if not part:IsA("Model") then return false end
		local parent, spawns = part.Parent, Workspace:FindFirstChild("NPCSpawns")
		return part.Name == "Gyakusatsu" and parent == Workspace
			or parent and parent:IsA("BasePart") and parent.Parent == spawns
				and (parent.Name == "BossSpawns" or parent.Name == "GyakusatsuSpawn" or npcSpawns[parent.Name])
	end
	connect(Workspace.DescendantAdded, function(part)
		registerHazard(part); registerZone(part)
		if isSpawnObject(part) then nextScan = 0 end
	end)
	connect(Workspace.DescendantRemoving, function(part)
		hazards[part] = nil; zoneParts[part] = nil
		if isSpawnObject(part) then nextScan = 0 end
	end)
	connect(Input.WindowFocusReleased, function() release(); if not gameInput() then cancelMove() end end)
	connect(Input.WindowFocused, flushNativeReleases)
	connect(RunService.Heartbeat, function()
		if stopped then return end
		local ok, err = pcall(function()
			if not alive() then api:Stop(); return end
			applyMove()
			local now = os.clock()
			if not held then flushNativeReleases() end
			if held and (now >= releaseAt or not allowed()) then releaseKey() end
			if clickHeld and (now >= clickReleaseAt or not allowed()) then releaseClick() end
			if now >= nextTick then nextTick = now + 0.05; step(now) end
			if alive() then gameClick(now) end
		end)
		if not ok then api:Stop(); state.lastError = tostring(err); state.reason = "Stopped on error" end
	end)
	-- Run after the game's camera/face writers. Only rotation is touched here;
	-- there is no second position driver or camera/cursor mutation.
	RunService:BindToRenderStep(renderName, Enum.RenderPriority.Last.Value + 1, function()
		local ok, err = pcall(applyFacing)
		if not ok then api:Stop(); state.lastError = tostring(err); state.reason = "Stopped on error" end
	end)
	return api
end
]=],
hub = [=[--!nonstrict
return function(Maclib, makeController, scope, stop, makeServers, extra)
	local Players = game:GetService("Players")
	local Input = game:GetService("UserInputService")
	local RunService = game:GetService("RunService")
	local player = Players.LocalPlayer
	local view = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
	local window = Maclib:Window({
		Title = "Ro-Ghoul", Subtitle = "",
		Size = UDim2.fromOffset(math.min(900, math.max(650, view.X - 60)), math.min(660, math.max(500, view.Y - 60))),
