	local getBossStatus = extra.bossStatus()
	local ui = saved and saved.ui or {language="ru", antiAFK=true, menu=true, tab=1}
	antiAFK:SetEnabled(ui.antiAFK)
	local group = window:TabGroup()
	local farm = group:Tab({ Name = "Боссы", Image = "rbxassetid://18821914323" })
	local npcTab = group:Tab({ Name = "NPC", Image = "rbxassetid://18821914323" })
	local automation = group:Tab({ Name = "Автоматика", Image = "rbxassetid://10734950309" })
	local statusTab = group:Tab({ Name = "Состояние", Image = "rbxassetid://10723407389" })
	local priorityTab = group:Tab({ Name = "Приоритет", Image = "rbxassetid://10723407389" })
	local trainerTab = group:Tab({ Name = "Тренеры", Image = "rbxassetid://10734950309" })
	local npcTargets, npcOptions = npcTab:Section({ Side = "Left" }), npcTab:Section({ Side = "Right" })
	local priorityEdit, priorityView = priorityTab:Section({ Side = "Left" }), priorityTab:Section({ Side = "Right" })
	local movement, attacks = farm:Section({ Side = "Left" }), farm:Section({ Side = "Right" })
	local equipment, allies = automation:Section({ Side = "Left" }), automation:Section({ Side = "Right" })
	local monitoring, statistics = statusTab:Section({ Side = "Left" }), statusTab:Section({ Side = "Right" })
	local sessionStatistics = statusTab:Section({ Side = "Right" })
	local trainerSetup, trainerMonitor = trainerTab:Section({ Side = "Left" }), trainerTab:Section({ Side = "Right" })
	local toggles = {}
	local controls: { [string]: any } = {}
	local skills = { E = false, R = false, F = false, C = false }
	local syncing = false
	local servers
	local flushPreferences, savingHeld = function() end, false
	local function toggle(section, name, option)
		local element = section:Toggle({ Name = name, Default = false,
			Callback = function(setting)
				if not syncing and not (servers and servers:GetStatus().busy) then
					if setting and (option == "farm" or option == "npcFarm" or option == "autoClick") then controller:SetStartupCombatHeld(false) end
					controller:SetOption(option, setting)
					if setting and (option == "farm" or option == "npcFarm" or option == "autoClick") then
						syncing = true
						for _, key in ipairs({ "farm", "npcFarm", "autoClick" }) do
							local control = controls[key]
							if control and control:GetState() ~= controller.options[key] then control:UpdateState(controller.options[key]) end
						end
						syncing = false
					end
				end
			end })
		if option ~= "bossPriorityEnabled" then table.insert(toggles, element) end
		controls[option] = element
		return element
	end
	local function pauseAll()
		if servers then servers:Cancel() end
		for _, name in ipairs({ "farm", "npcFarm", "autoClick", "autoArata", "autoMask", "autoAlly", "autoTrainer", "godMode" }) do controller:SetOption(name, false) end
		for key in pairs(skills) do skills[key] = false end
		controller:SetOption("skills", skills)
		syncing = true
		for _, element in ipairs(toggles) do element:UpdateState(false) end
		syncing = false
	end
	servers = makeServers(scope, function() flushPreferences(true); savingHeld=true; pauseAll() end, stop,
		{ onBusy = function(busy) controller:SetSuspended(busy); savingHeld=busy end })
	local function stopButton(section)
		section:Button({ Name = "Остановить все функции", Callback = pauseAll })
	end
	local function bossNames()
		local known = { Gyakusatsu = true } -- Observed paths; phase-aware combat remains experimental.
		for _, name in ipairs(controller.options.bossPriority) do known[name] = true end
		for name in pairs(controller.options.selectedBosses) do known[name] = true end
		for _, name in ipairs(controller:GetBossNames()) do known[name] = true end
		local folder = player:FindFirstChild("PlayerFolder")
		local kills = folder and folder:FindFirstChild("BossKills")
		if kills then for _, counter in ipairs(kills:GetChildren()) do known[counter.Name] = true end end
		local names = {}
		for name in pairs(known) do table.insert(names, name) end
		table.sort(names)
		return names
	end
	local cachedBossNames = bossNames()
	movement:Header({ Text = "Цели и перемещение" })
