		for _, name in ipairs(cachedBossNames) do if not bossDropdown:IsOption(name) then table.insert(additions, name) end end
		if #additions > 0 then bossDropdown:InsertOptions(additions) end
	end })
	toggle(movement, "Auto Farm / Tween", "farm")
	toggle(movement, "Приоритет боссов", "bossPriorityEnabled")
	controls.priorityOpen = movement:Button({ Name = "Изменить порядок приоритета", Callback = function() priorityTab:Select() end })
