		Default = "Behind", Required = true, Callback = function(selection) controller:SetOption("farmMethod", selection) end })
	controls.distance = movement:Slider({ Name = "Дистанция (studs)", Default = 8, Minimum = 2, Maximum = 40,
		DisplayMethod = "Value", Precision = 0, Callback = function(setting) controller:SetOption("distance", setting) end })
	controls.moveSpeed = movement:Slider({ Name = "Скорость (studs/с)", Default = 60, Minimum = 20, Maximum = 400,
		DisplayMethod = "Value", Precision = 0, Callback = function(setting) controller:SetOption("moveSpeed", setting) end })
	stopButton(movement)
