		Options = controller:GetNPCNames(), Default = {}, Callback = function(selection)
			if not syncing then controller:SetOption("selectedNPCs", selection) end
		end })
	controls.selectedNPCs = npcDropdown
	local function updateNPCList()
		local additions = {}
		for _, name in ipairs(controller:GetNPCNames()) do if not npcDropdown:IsOption(name) then table.insert(additions, name) end end
		if #additions > 0 then npcDropdown:InsertOptions(additions) end
	end
	controls.refreshNPCs = npcTargets:Button({ Name = "Обновить список NPC", Callback = updateNPCList })
	toggle(npcTargets, "Фарм NPC / Tween", "npcFarm")
	stopButton(npcTargets)
	npcOptions:Header({ Text = "Поглощение" })
	-- Keep saved numeric preferences compatible; the visible control is a native on/off Toggle.
	controls.absorbNPC = npcOptions:Toggle({ Name = "Поглощать трупы", Default = false, Callback = function(setting)
			if not syncing then controller:SetOption("absorbNPC", setting and 1 or 0) end
		end })
	attacks:Header({ Text = "Атаки и навыки" })
	controls.weaponStage = attacks:Dropdown({ Name = "Стадия оружия (1–9)", Multi = false, Required = true,
		Options = { "1", "2", "3", "4", "5", "6", "7", "8", "9" }, Default = "1",
		Callback = function(selection)
			if not syncing then controller:SetOption("weaponStage", tonumber(selection)) end
		end })
	toggle(attacks, "Автоклик / левая кнопка", "autoClick")
	controls.clickInterval = attacks:Slider({ Name = "Пауза кликов (с)", Default = 0.05, Minimum = 0.02, Maximum = 1,
		DisplayMethod = "Value", Precision = 2, Callback = function(setting) controller:SetOption("clickInterval", setting) end })
	for _, key in ipairs({ "E", "R", "F", "C" }) do
		local element = attacks:Toggle({ Name = "Навык " .. key, Default = false,
			Callback = function(setting)
				if syncing or servers:GetStatus().busy then return end
