				skills[key] = setting
				controller:SetOption("skills", skills)
			end })
		table.insert(toggles, element)
		controls[key] = element
	end
	controls.cMode = attacks:Dropdown({ Name = "Режим C", Options = { "Use", "Toggle" }, Default = "Use", Required = true,
		Callback = function(selection) controller:SetOption("cMode", selection) end })
	controls.skillInterval = attacks:Slider({ Name = "Пауза навыков (с)", Default = 0.5, Minimum = 0.15, Maximum = 3,
		DisplayMethod = "Value", Precision = 2, Callback = function(setting) controller:SetOption("skillInterval", setting) end })
	priorityEdit:Header({ Text = "Изменить порядок" })
