	controls.priorityBoss = priorityEdit:Dropdown({ Name = "Босс", Search = true, Options = cachedBossNames, Default = priorityName,
		Required = true, Callback = function(selection) priorityName = selection end })
	local priorityOrder = priorityView:Paragraph({ Header = "Приоритет выключен", Body = "" })
	local function updatePriority()
		local lines = {}
		for index, name in ipairs(controller.options.bossPriority) do table.insert(lines, tostring(index) .. ". " .. name) end
		priorityOrder:UpdateHeader(controller.options.bossPriorityEnabled and "Порядок приоритета" or "Приоритет выключен")
		priorityOrder:UpdateBody(table.concat(lines, "\n"))
	end
	local function reorder(delta)
		if servers:GetStatus().busy or not priorityName then return end
		local order = table.clone(controller.options.bossPriority)
		local index = table.find(order, priorityName)
		if not index then table.insert(order, priorityName); index = #order end
		local destination = math.clamp(index + delta, 1, #order)
		order[index], order[destination] = order[destination], order[index]
		controller:SetOption("bossPriority", order); updatePriority()
	end
	controls.priorityUp = priorityEdit:Button({ Name = "Поднять выше ↑", Callback = function() reorder(-1) end })
	controls.priorityDown = priorityEdit:Button({ Name = "Опустить ниже ↓", Callback = function() reorder(1) end })
	controls.priorityOrder = priorityOrder
	updatePriority()
	equipment:Header({ Text = "Экипировка" })
	toggle(equipment, "Auto Arata", "autoArata")
	toggle(equipment, "Auto Mask", "autoMask")
	toggle(equipment, "God Mode / Anti-Death", "godMode")
	equipment:SubLabel({ Text = "Серверный урон не подменяется: при низком HP скрипт быстро отходит, сохраняет цель и возвращается после восстановления." })
	stopButton(equipment)
	allies:Header({ Text = "Союзники" })
	toggle(allies, "Auto Ally All", "autoAlly")
	allies:Header({ Text = "Сервер" })
	controls.serverHop = allies:Button({ Name = "Server Hop", Callback = function() servers:Request("Hop") end })
	controls.rejoin = allies:Button({ Name = "Rejoin", Callback = function() servers:Request("Rejoin") end })
	local serverStatus = allies:Paragraph({ Header = "Состояние сервера", Body = "Готово" })
	trainerSetup:Header({ Text = "Автоматические тренеры" })
