	monitoring:Header({ Text = "Текущий запуск" })
	local summary = monitoring:Paragraph({ Header = "Ожидание", Body = "Все функции выключены." })
	local bossStatus = statistics:Paragraph({ Header = "Статус", Body = "" })
	local sessionStatus = sessionStatistics:Paragraph({ Header = "Сессия", Body = "" })
