	local locale
	controls.language = allies:Dropdown({ Name = "Язык / Language", Options = {"Русский", "English"}, Required = true,
		Default = ui.language == "en" and "English" or "Русский", Callback = function(value)
			if syncing then return end
			ui.language = value == "English" and "en" or "ru"
			if locale then locale:SetLanguage(ui.language) end
		end })
	controls.antiAFK = allies:Toggle({ Name = "Anti-AFK", Default = ui.antiAFK ~= false, Callback = function(value) ui.antiAFK=value; antiAFK:SetEnabled(value) end })
	local configStatus = allies:Paragraph({ Header = "Сохранение настроек", Body = preferences.message })
	controls.savePreferences = allies:Button({ Name = "Сохранить сейчас", Callback = function() flushPreferences(true) end })
	stopButton(monitoring)
	scope.connect(Input.InputBegan, function(input, processed)
		if not processed and not Input:GetFocusedTextBox() and input.KeyCode == Enum.KeyCode.F8 then pauseAll() end
	end)
	local reasons = { ["Idle"] = "Ожидание", ["Active"] = "Активно", ["Menu open"] = "Пауза: системное меню Roblox",
		["Waiting for manual start"] = "Ожидание ручного запуска",
		["Waiting for game input"] = "Ожидание игрового обработчика",
		["Suspended"] = "Пауза: проверка",
		["Roblox unfocused"] = "Пауза: Roblox не в фокусе", ["Typing"] = "Пауза: ввод текста",
		["Waiting for character"] = "Ожидание персонажа", ["Cannot act"] = "Персонаж занят",
		["Target in safe zone"] = "Защищённые цели временно пропущены",
		["Waiting for safe zone data"] = "Ожидание данных безопасных зон",
		["Waiting for Gyakusatsu"] = "Ожидание целей Gyakusatsu",
		["Waiting for locked boss"] = "Ожидание данных закреплённого босса",
		["No selected boss alive"] = "Ожидание выбранного босса", ["No bosses selected"] = "Цели не выбраны",
		["No selected NPC alive"] = "Ожидание выбранного NPC", ["No NPCs selected"] = "NPC не выбраны",
		["Waiting for corpse"] = "Ожидание трупа", ["Moving to corpse"] = "Перемещение к трупу", ["Absorbing NPC"] = "Попытка поглощения NPC",
		["Target not visible or cursor blocked"] = "Цель закрыта или вне экрана", ["Stopped"] = "Остановлено",
		["Stopped on error"] = "Остановлено из-за ошибки", ["Unsupported game"] = "Открыт другой режим",
		["Moving to boss"] = "Перемещение к боссу", ["Movement interrupted"] = "Перемещение прервано",
		["Moving to NPC"] = "Перемещение к NPC",
		["Recovering position"] = "Пересчёт после смещения",
		["Safety pause"] = "Пауза: проверка безопасного пути",
		["Equipping Arata"] = "Ожидание надевания Arata", ["Equipping mask"] = "Ожидание надевания маски",
		["Waiting for equipment state"] = "Ожидание данных экипировки", ["Arata unavailable"] = "Arata не выбрана / недоступна",
		["Planning route"] = "Поиск безопасного пути", ["Unsafe route"] = "Путь небезопасен",
		["Equipping weapon"] = "Ожидание доставания оружия", ["Native aim locked"] = "Нативный прицел заблокирован",
		["God Mode retreat"] = "God Mode: защитный отход", ["God Mode recovery"] = "God Mode: восстановление HP",
		["Trainer active"] = "Авто-тренер активен" }
	local trainerStates = { Idle = "Ожидание", ["Trainer not owned"] = "Тренер не открыт", ["Trainer complete"] = "Тренер завершён",
		["All trainers complete"] = "Все тренеры завершены", ["No owned trainers"] = "Нет доступных тренеров", Training = "Тренировка идёт",
		["Waiting for trainer remote"] = "Ожидание сервера тренеров", ["Starting trainer"] = "Запуск тренировки",
		["Waiting for training client"] = "Ожидание клиента тренировки", ["Completing training"] = "Автопрохождение тренировки",
		["Finishing training"] = "Завершение тренировки", ["Trainer waiting"] = "Ожидание следующей попытки", ["Trainer error"] = "Ошибка тренера" }
	local nextUpdate, nextList = 0, 0
	scope.connect(RunService.Heartbeat, function()
		local now = os.clock()
		if now >= nextList then
			nextList = now + 2
			resources:Refresh()
			updateNPCList()
			updateTrainerList()
			cachedBossNames = bossNames()
			local additions = {}
			for _, name in ipairs(cachedBossNames) do if not bossDropdown:IsOption(name) then table.insert(additions, name) end end
			if #additions > 0 then bossDropdown:InsertOptions(additions) end
			local priorityAdditions = {}
			for _, name in ipairs(cachedBossNames) do if not controls.priorityBoss:IsOption(name) then table.insert(priorityAdditions, name) end end
			if #priorityAdditions > 0 then controls.priorityBoss:InsertOptions(priorityAdditions) end
		end
		if now < nextUpdate then return end
		nextUpdate = now + 0.5
		local status = controller:GetStatus()
		flushPreferences(false)
		configStatus:UpdateBody(preferences.message .. (antiAFK.lastError and "\nAnti-AFK / Ошибка: " .. antiAFK.lastError or ""))
		local spawns, lines = getBossStatus(cachedBossNames), {}
		local function escape(text) return text:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"):gsub('"', "&quot;") end
		for _, name in ipairs(cachedBossNames) do
			table.insert(lines, escape(name) .. ': <font color="' .. (spawns[name] and "#63D98B" or "#F27D7D") .. '">' .. (spawns[name] and "Заспавнен" or "Не заспавнен") .. '</font>')
		end
		bossStatus:UpdateBody(table.concat(lines,"\n"))
		local gains, resourceLines = resources:GetStatus(), {}
		for _, entry in ipairs({{"Yen","Yen"},{"RC","RC"},{"Reputation","Репутация"},{"Hearts","Сердца"}}) do
			local row = gains[entry[1]]
			table.insert(resourceLines, entry[2] .. ": " .. string.format("%.0f",row.gained) .. (not row.available and " / нет данных" or ""))
		end
		sessionStatus:UpdateBody(table.concat(resourceLines,"\n"))
		updatePriority()
		local transfer = servers:GetStatus()
		serverStatus:UpdateBody(transfer.message)
		controls.serverHop:UpdateName(transfer.busy and transfer.kind == "Hop" and "Server Hop — ожидание…" or "Server Hop")
		controls.rejoin:UpdateName(transfer.busy and transfer.kind == "Rejoin" and "Rejoin — ожидание…" or "Rejoin")
		-- Reflect explicit option changes without running their callbacks again.
		local stage = tostring(controller.options.weaponStage)
		if controls.weaponStage.Value ~= stage then
			syncing = true; controls.weaponStage:UpdateSelection(stage); syncing = false
		end
		if controls.absorbNPC:GetState() ~= (controller.options.absorbNPC == 1) then
			syncing = true; controls.absorbNPC:UpdateState(controller.options.absorbNPC == 1); syncing = false
		end
		local npcSelection, npcChanged = {}, false
		for name, chosen in pairs(npcDropdown:GetOptions()) do
			local expected = controller.options.selectedNPCs[name] == true
			if chosen ~= expected then npcChanged = true end
			if expected then table.insert(npcSelection, name) end
		end
		if npcChanged then syncing = true; npcDropdown:UpdateSelection(npcSelection); syncing = false end
		for _, name in ipairs({ "farm", "npcFarm", "autoClick", "autoArata", "autoMask", "autoAlly", "autoTrainer", "godMode", "bossPriorityEnabled" }) do
			if controls[name]:GetState() ~= controller.options[name] then
				syncing = true; controls[name]:UpdateState(controller.options[name]); syncing = false
			end
		end
		for key in pairs(skills) do
			if controls[key]:GetState() ~= controller.options.skills[key] then
				syncing = true; controls[key]:UpdateState(controller.options.skills[key]); syncing = false
			end
		end
		local selected, enabled = {}, {}
		for name in pairs(controller.options.selectedBosses) do table.insert(selected, name) end
		table.sort(selected)
		for _, name in ipairs({ "farm", "npcFarm", "autoClick", "autoArata", "autoMask", "autoAlly", "autoTrainer", "godMode" }) do
			if controller.options[name] then table.insert(enabled, name == "godMode" and "God Mode" or name) end
		end
		for _, key in ipairs({ "E", "R", "F", "C" }) do if skills[key] then table.insert(enabled, key) end end
		local body = "Цель: " .. (status.target or "—") .. "\nВыбрано: " .. tostring(#selected)
			.. "\nТип цели: " .. (status.targetKind == "NPC" and "NPC" or status.targetKind == "Corpse" and "труп NPC" or status.targetKind == "Boss" and "босс" or "—")
			.. "\nЗакреплён: " .. (status.lockedBoss or "—")
			.. "\nМетод: " .. controller.options.farmMethod .. (status.holdingPosition and " / удержание" or "")
			.. "\nСтадия оружия: " .. stage
			.. "\nНаведение: " .. (status.facingTarget and "на цель" or "неактивно")
			.. "\nВключено: " .. (#enabled > 0 and table.concat(enabled, ", ") or "нет")
			.. "\nВвод: " .. (status.inputMode == "Game action" and "игровой обработчик / фон" or status.inputMode == "Unavailable" and "игровой обработчик недоступен" or status.inputMode == "Trainer remote" and "тренер / сервер" or "нативный")
		if controller.options.selectedBosses.Gyakusatsu then
			local phases = { Hearts = "сердца", Boss = "босс", ["Waiting for hearts"] = "загрузка сердец",
				["Waiting for boss"] = "ожидание второй стадии", Absent = "не появился" }
			body ..= "\nGyakusatsu: " .. (phases[status.gyakusatsuPhase] or status.gyakusatsuPhase)
				.. " / живых сердец: " .. tostring(status.gyakusatsuHearts)
		end
		if controller.options.cMode == "Toggle" then
			body ..= "\nC Toggle: " .. (not status.cWeaponAvailable and "ожидание оружия"
				or status.cToggleSent and "попытка уже выполнена" or "одна попытка при атаке")
		end
		if controller.options.godMode then
			body ..= "\nGod Mode: " .. (status.survivalActive and "защитный отход / восстановление" or "готов")
			if status.survivalHealth then body ..= string.format(" / HP %.0f%%", status.survivalHealth) end
			body ..= " / спасений: " .. tostring(status.survivalRetreats) .. " / возвратов: " .. tostring(status.survivalResumes)
		end
		if status.pendingNativeReleases > 0 then body ..= "\nОтпускание клавиш ожидает фокуса Roblox" end
		if status.recoveryRemaining > 0 then body ..= string.format("\nВосстановление: %.1f с", status.recoveryRemaining) end
		if status.lastError then body ..= "\nОшибка: " .. status.lastError end
		local selectedNPCs = 0
		for _ in pairs(controller.options.selectedNPCs) do selectedNPCs += 1 end
		body ..= "\nВыбрано NPC: " .. tostring(selectedNPCs)
			.. "\nПоглощение: " .. (controller.options.absorbNPC == 1 and "включено" or "выключено")
			.. "\nСмерти NPC: " .. tostring(status.npcDeaths) .. "\nПопытки поглощения: " .. tostring(status.absorbAttempts)
		local trainerBody = "Режим: " .. controller.options.selectedTrainer
			.. "\nФракция: " .. (status.trainerFaction or "—")
			.. "\nТренер: " .. (status.trainerTarget or "—")
			.. "\nПрогресс: " .. (status.trainerProgress and string.format("%.0f%%", status.trainerProgress) or "—")
			.. "\nСтатус: " .. (trainerStates[status.trainerStatus] or status.trainerStatus or "Ожидание")
			.. "\nЗапросы: " .. tostring(status.trainerAttempts) .. " / приняты: " .. tostring(status.trainerAccepted)
			.. "\nАвтопрохождения: " .. tostring(status.trainerCompleted)
		if status.trainerFinishMode then trainerBody ..= "\nМетод завершения: " .. status.trainerFinishMode end
		if status.trainerResponse and status.trainerResponse ~= "nil" then trainerBody ..= "\nОтвет: " .. status.trainerResponse end
		trainerStatus:UpdateHeader(controller.options.autoTrainer and "Авто-тренер активен" or "Ожидание")
		trainerStatus:UpdateBody(controller.options.autoTrainer and trainerBody or "Авто-тренеры выключены.")
		summary:UpdateHeader(transfer.busy and "Пауза: переход на сервер" or reasons[status.reason] or status.reason)
		summary:UpdateBody(body)
	end)
	-- Synchronize loaded preferences without invoking action callbacks.
	syncing=true
	controls.language:UpdateSelection(ui.language == "en" and "English" or "Русский")
	for key, element in pairs(controls) do
		local option=controller.options[key]
		if option ~= nil then
			if element.Class == "Toggle" then element:UpdateState(key == "absorbNPC" and option == 1 or option == true)
			elseif element.Class == "Slider" then element:UpdateValue(option)
			elseif element.Class == "Dropdown" then
				if key == "selectedBosses" or key == "selectedNPCs" then
					local selection={}; for name,chosen in pairs(option) do if chosen then if not element:IsOption(name) then element:InsertOptions({name}) end; table.insert(selection,name) end end
					element:UpdateSelection(selection)
				elseif key == "selectedTrainer" then
					if not element:IsOption(option) then element:InsertOptions({option}) end
					element:UpdateSelection(option)
				else element:UpdateSelection(key == "weaponStage" and tostring(option) or option) end
			end
		end
	end
	for key in pairs(skills) do skills[key]=controller.options.skills[key]; controls[key]:UpdateState(skills[key]) end
	syncing=false
	local tabs = {farm, automation, statusTab, priorityTab, npcTab, trainerTab}
	tabs[ui.tab or 1]:Select()
	local root = gethui and gethui() or game:GetService("CoreGui")
	local base
	for _, object in ipairs(root:GetDescendants()) do
		if object:IsA("TextLabel") and object.Text == "Ro-Ghoul" then
			local a=object.Parent; while a and a.Name ~= "Base" do a=a.Parent end
			if a then base=a end
		end
	end
	assert(base,"Original Maclib Base missing")
	local palette = {
		shell = Color3.fromRGB(8, 17, 24), glass = Color3.fromRGB(18, 35, 45),
		surface = Color3.fromRGB(16, 27, 35), raised = Color3.fromRGB(23, 39, 49),
		accent = Color3.fromRGB(91, 217, 239), accentSoft = Color3.fromRGB(126, 228, 245),
		text = Color3.fromRGB(234, 247, 250), muted = Color3.fromRGB(175, 205, 214),
	}
	base:SetAttribute("RGHTheme", "LiquidGlass")
	base.BackgroundColor3, base.BackgroundTransparency, base.ClipsDescendants = palette.shell, 0.08, true
	local gradient = Instance.new("UIGradient")
	gradient.Name = "LiquidGlassGradient"
	gradient.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, Color3.fromRGB(12, 29, 39)),
		ColorSequenceKeypoint.new(0.55, palette.shell),
		ColorSequenceKeypoint.new(1, Color3.fromRGB(8, 22, 31)),
	})
	gradient.Rotation = 24
	gradient.Parent = base
	local function liquidStyle(object)
		if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
			object.TextColor3 = palette.text
			if object.Name == "HeaderText" then object.TextColor3, object.TextTransparency = palette.accentSoft, 0
			elseif object.Name == "SubLabelText" then object.TextColor3, object.TextTransparency = palette.muted, math.min(object.TextTransparency, 0.22)
			elseif object.Name == "ParagraphBody" then object.TextColor3, object.TextTransparency = palette.muted, math.min(object.TextTransparency, 0.12)
			elseif object.Name == "ParagraphHeader" then object.TextTransparency = math.min(object.TextTransparency, 0.04)
			elseif object.Name == "ToggleName" or object.Name == "SliderName" or object.Name == "DropdownName" or object.Name == "ButtonInteract" then
				object.TextTransparency = math.min(object.TextTransparency, 0.14)
			end
			if object:IsA("TextBox") then object.PlaceholderColor3 = palette.muted end
		elseif object:IsA("ScrollingFrame") then
			object.ScrollBarImageColor3, object.ScrollBarImageTransparency = palette.accent, 0.25
		elseif object:IsA("ImageLabel") or object:IsA("ImageButton") then
			if object.Name == "TabImage" or object.Name == "DropdownImage" or object.Name == "ButtonImage" or object.Name == "SearchIcon" then object.ImageColor3 = palette.accentSoft end
		end
		if object.Name == "Sidebar" and object:IsA("Frame") then object.BackgroundColor3, object.BackgroundTransparency = palette.glass, 0.28 end
		if object.Name == "Dropdown" and object:IsA("Frame") then object.BackgroundColor3, object.BackgroundTransparency = palette.raised, 0.08 end
		if object.Name == "Search" and object:IsA("Frame") then object.BackgroundColor3, object.BackgroundTransparency = palette.raised, 0.16 end
		if object:IsA("UIStroke") and (object.Name == "BaseUIStroke" or object.Name == "SectionUIStroke" or object.Name == "DropdownUIStroke" or object.Name == "TabSwitcherUIStroke") then
			object.Color = palette.accent
		end
	end
	liquidStyle(base)
	for _, object in ipairs(base:GetDescendants()) do liquidStyle(object) end
	scope.connect(base.DescendantAdded,liquidStyle)
	-- Maclib's default Paragraph opacity would halve the colored status contrast.
	local function statusContrast(object)
		if object.Name ~= "ParagraphBody" or not object:IsA("TextLabel") then return end
		local header=object.Parent and object.Parent:FindFirstChild("ParagraphHeader")
		if header and (header.Text == "Статус" or header.Text == "Status") then object.TextTransparency=0 end
	end
	for _, object in ipairs(base:GetDescendants()) do statusContrast(object) end
	scope.connect(base.DescendantAdded,statusContrast)
	if ui.size then window:SetSize(UDim2.new(unpack(ui.size))) end
	if ui.scale then window:SetScale(ui.scale) end
	if ui.position then
		local p=UDim2.new(unpack(ui.position)); local size=window:GetSize(); local halfX,halfY=size.X.Offset/2,size.Y.Offset/2
		local x,y=p.X.Scale*view.X+p.X.Offset,p.Y.Scale*view.Y+p.Y.Offset
		local boundedX,boundedY=math.clamp(x,math.min(halfX,view.X/2),math.max(view.X-halfX,view.X/2)),math.clamp(y,math.min(halfY,view.Y/2),math.max(view.Y-halfY,view.Y/2))
		base.Position=(boundedX==x and boundedY==y) and p or UDim2.fromOffset(boundedX,boundedY)
	end
	window:SetState(ui.menu ~= false)
	locale=extra.locale(scope,base.Parent,ui.language)
	local http=game:GetService("HttpService")
	local function capture()
		local p,s=base.Position,window:GetSize()
		local current=base:FindFirstChild("CurrentTab",true)
		local currentText=current and current.Text
		for index,tab in ipairs(tabs) do if currentText==tab.Settings.Name or currentText==locale:Translate(tab.Settings.Name) then ui.tab=index end end
		return {options=controller.options,ui={language=ui.language,antiAFK=antiAFK.enabled,menu=window:GetState(),tab=ui.tab or 1,
			position={p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset},size={s.X.Scale,s.X.Offset,s.Y.Scale,s.Y.Offset},scale=window:GetScale()}}
	end
	local function equal(a,b)
		if type(a)~=type(b) then return false end
		if type(a)~="table" then return a==b end
		for k,v in pairs(a) do if not equal(v,b[k]) then return false end end
		for k in pairs(b) do if a[k]==nil then return false end end
		return true
	end
	local last=http:JSONDecode(http:JSONEncode(capture()))
	local dirtyAt, retryAt
	flushPreferences=function(force)
		if savingHeld then return end
		local snapshot=capture(); local now=os.clock()
		if not equal(snapshot,last) then dirtyAt=dirtyAt or now end
		if force or dirtyAt and now-dirtyAt>=0.6 and (not retryAt or now>=retryAt) then
			if preferences:Save(snapshot.options,snapshot.ui) then last=http:JSONDecode(http:JSONEncode(snapshot)); dirtyAt=nil; retryAt=nil
			else retryAt=now+10 end
		end
	end
	scope.onCleanup(function() if dirtyAt or not equal(capture(),last) then flushPreferences(true) end end)
	-- Public diagnostic indexes stay compatible; Trainers is appended as index 6.
	return window, controller, { Controls = controls, Tabs = tabs, PauseAll = pauseAll, Servers = servers,
		ResourceSession=resources, Preferences=preferences, Locale=locale, AntiAFK=antiAFK, Base=base, FlushPreferences=flushPreferences }
end
]=],
servers = [=[--!nonstrict
-- Scoped, single-flight transfers. Loading the factory has no side effects.
return function(scope, pauseAll, onTransfer, injected)
	local deps = injected or {}
	local player = deps.player or game:GetService("Players").LocalPlayer
	local http = deps.http or game:GetService("HttpService")
	local teleport = deps.teleport or game:GetService("TeleportService")
	local placeId, jobId = deps.placeId or game.PlaceId, deps.jobId or game.JobId
	local spawn, delay = deps.spawn or task.spawn, deps.delay or task.delay
	local sendRequest = deps.request or request
	local onBusy = deps.onBusy or function(_busy) end
	local stopped, operation = false, nil
	local state = { busy = false, phase = "Idle", message = "Готово", attempts = 0, pages = 0 }
	local api = {}
	local function current(token) return not stopped and scope.alive() and operation == token end
	local function finish(token, phase, message)
		if not current(token) then return end
		operation, state.busy, state.phase, state.message = nil, false, phase, message
		onBusy(false)
	end
	function api:GetStatus() return table.clone(state) end
	function api:Cancel()
		if operation then
			operation = nil; state.busy, state.phase, state.message = false, "Cancelled", "Отменено"
			onBusy(false)
		end
	end
	function api:Stop() self:Cancel(); stopped = true end
	local function dispatch(token, serverId)
		if not current(token) then return end
		state.phase, state.message, state.serverId = "Teleporting", "Подключение…", serverId
		-- All farm/native inputs and owned movement are already released by pauseAll.
		local ok, err = pcall(function()
			if serverId then teleport:TeleportToPlaceInstance(placeId, serverId, player)
			else teleport:Teleport(placeId, player) end
		end)
		if not ok then finish(token, "Error", "Переход не выполнен: " .. tostring(err)); return end
		delay(20, function() finish(token, "Error", "Переход не подтвердился. Попробуйте снова.") end)
	end
	function api:Request(kind)
		if stopped or not scope.alive() or state.busy or (kind ~= "Hop" and kind ~= "Rejoin") then return false end
		pauseAll() -- Also invalidates any previous cancelled lookup before issuing a new token.
		local token = {}; operation = token
		state.busy, state.kind, state.attempts, state.pages, state.serverId = true, kind, state.attempts + 1, 0, nil
		onBusy(true)
		if kind == "Rejoin" then dispatch(token, jobId ~= "" and jobId or nil); return true end
		state.phase, state.message = "Searching", "Поиск свободного сервера…"
		delay(15, function()
			if current(token) and state.phase == "Searching" then finish(token, "Error", "Поиск превысил 15 с. Попробуйте снова.") end
		end)
		spawn(function()
			local ok, err = pcall(function()
				local cursor, seen = nil, {}
				for page = 1, 3 do
					if not current(token) then return end
					state.pages = page
					local url = "https://games.roblox.com/v1/games/" .. tostring(placeId)
						.. "/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"
					if cursor then url ..= "&cursor=" .. http:UrlEncode(cursor) end
					local response = sendRequest({ Url = url, Method = "GET" })
					if not current(token) then return end
					if type(response) ~= "table" or response.StatusCode ~= 200 or response.Success == false then
						error("Список серверов недоступен (HTTP " .. tostring(type(response) == "table" and response.StatusCode or "ошибка запроса") .. ").", 0)
					end
					local body = http:JSONDecode(response.Body)
					if type(body) ~= "table" or type(body.data) ~= "table" then error("Неверный ответ списка серверов.", 0) end
					for _, server in ipairs(body.data) do
						if type(server) == "table" and type(server.id) == "string" and #server.id == 36
							and server.id:match("^%x+%-%x+%-%x+%-%x+%-%x+$") and server.id ~= jobId
							and type(server.playing) == "number" and type(server.maxPlayers) == "number"
							and server.playing >= 0 and server.playing < server.maxPlayers and server.maxPlayers < math.huge then
							dispatch(token, server.id); return
						end
					end
					cursor = body.nextPageCursor
					if type(cursor) ~= "string" or cursor == "" or seen[cursor] then break end
					seen[cursor] = true
				end
				finish(token, "Error", "Другой неполный сервер не найден. Попробуйте позже.")
			end)
			if not ok then finish(token, "Error", tostring(err)) end
		end)
		return true
	end
	scope.connect(teleport.TeleportInitFailed, function(who, result, message, failedPlace, failedOptions)
		if who == player and operation and state.phase == "Teleporting" and (not failedPlace or failedPlace == placeId) then
			-- Where Roblox supplies an instance ID, do not attribute an old/different transfer's failure to this one.
			local failedId = failedOptions and failedOptions.ServerInstanceId
			if failedId and failedId ~= "" and failedId ~= state.serverId then return end
			finish(operation, "Error", "Переход не выполнен: " .. tostring(message or result))
		end
	end)
	scope.connect(player.OnTeleport, function(setting)
		if not operation or state.phase ~= "Teleporting" then return end
		if setting == Enum.TeleportState.Failed then finish(operation, "Error", "Roblox отклонил переход. Попробуйте снова.")
		elseif setting == Enum.TeleportState.InProgress then
			state.phase, state.message = "Leaving", "Переход на сервер…"
			onTransfer() -- Exact runtime/guard/listener cleanup after Roblox confirms departure.
		end
	end)
	scope.onCleanup(function() api:Stop() end)
	return api
end
]=],
clientComGuard = [=[--!nonstrict
-- Guard only the verified game's packet consumer; no global WaitForChild/log hook.
return function(scope)
	local player = game:GetService("Players").LocalPlayer
	local run = game:GetService("RunService")
	local com = workspace:FindFirstChild("ClientCom")
	local scriptObject = player.PlayerScripts and player.PlayerScripts:FindFirstChild("ClientCom")
	local state = { active = false, forwarded = 0, deferred = 0, dropped = 0, pending = 0, reason = "Unavailable" }
	local api = {}
	function api:GetStatus() return table.clone(state) end
	if game.PlaceId ~= 914010731 or game.GameId ~= 380704901 or game.PlaceVersion ~= 7510
		or not com or not scriptObject or type(getconnections) ~= "function" then return api end
	local original
	for _, connection in ipairs(getconnections(com.ChildAdded)) do
		local callback = connection.Function
		if callback and connection.Enabled == true and getfenv(callback).script == scriptObject then
			if original then state.reason = "Ambiguous consumer"; return api end
			original = connection
		end
	end
	if not original or type(original.Disable) ~= "function" or type(original.Enable) ~= "function" then return api end
	local callback, pending, stopped = original.Function, {}, false
	local schemas = {
		Woosh = { fields = { "Center", "Speed", "Vol", "Pitch", "EmitSize", "FallOffDist" },
			numbers = { "Speed", "Vol", "Pitch", "EmitSize", "FallOffDist" } },
		Blood = { fields = { "Center", "Speed", "Rate1", "Rate2", "Vol" }, numbers = { "Speed", "Rate1", "Rate2", "Vol" } },
		Bludgeon = { fields = { "Center", "Speed", "Rate1", "Rate2", "Vol", "Size", "Locked" },
			numbers = { "Speed", "Rate1", "Rate2", "Vol", "Size" } },
		SafeZoneSwitch = { fields = { "TPlayer", "Bool" }, numbers = {} },
	}
	local function ready(packet, schema)
		for _, name in ipairs(schema.fields) do
			local child = packet:FindFirstChild(name)
			if not child or not child:IsA("ValueBase") then return false end
		end
		for _, name in ipairs(schema.numbers) do
			local number = tonumber(packet:FindFirstChild(name).Value)
			if not number or number ~= number or math.abs(number) == math.huge then return false end
		end
		return true
	end
	local function remove(packet)
		local entry = pending[packet]
		if not entry then return end
		pending[packet] = nil; state.pending -= 1
		for _, connection in ipairs(entry.links) do connection:Disconnect() end
	end
	local function forward(packet)
		state.forwarded += 1
		callback(packet) -- complete known packets do not yield on absent children
	end
	local function process(packet)
		local entry = pending[packet]
		if not entry then return end
		if stopped or not scope.alive() or packet.Parent ~= com or os.clock() >= entry.deadline then
			remove(packet); state.dropped += 1
		elseif ready(packet, entry.schema) then
			remove(packet); forward(packet)
		end
	end
	local proxy, heartbeat
	local function stop()
		if stopped then return end
		stopped, state.active, state.reason = true, false, "Stopped"
		if proxy then proxy:Disconnect() end
		if heartbeat then heartbeat:Disconnect() end
		for packet in pairs(pending) do remove(packet) end
		original:Enable() -- only an originally enabled, exact ClientCom consumer was disabled
	end
	scope.onCleanup(stop)
	proxy = scope.connect(com.ChildAdded, function(packet)
		if stopped or not scope.alive() then return end
		local schema = schemas[packet.Name]
		if not schema then forward(packet); return end -- unrelated branches unchanged
		if packet.Parent ~= com then state.dropped += 1; return end
		if ready(packet, schema) then forward(packet); return end
		if state.pending >= 128 then state.dropped += 1; return end
		local entry = { schema = schema, deadline = os.clock() + 0.5, links = {} }
		pending[packet] = entry; state.pending += 1; state.deferred += 1
		-- These short-lived links are not retained in Runtime's long-lived connection list.
		table.insert(entry.links, packet.ChildAdded:Connect(function() process(packet) end))
		table.insert(entry.links, packet.AncestryChanged:Connect(function() process(packet) end))
		process(packet)
	end)
	heartbeat = scope.connect(run.Heartbeat, function()
		if stopped then return end
		if not scope.alive() or com.Parent ~= workspace or scriptObject.Parent ~= player.PlayerScripts then stop(); return end
		for packet in pairs(pending) do process(packet) end
	end)
	original:Disable()
	state.active, state.reason = true, "Verified ClientCom packet readiness guard"
	return api
end
