preferences = [=[--!nonstrict
-- Two verified JSON slots; no executable config, rename dependency or saved action dispatch.
return function(deps)
	local d = deps or {}
	local http = d.http or game:GetService("HttpService")
	local userId = d.userId or game:GetService("Players").LocalPlayer.UserId
	local exists, read, write = d.exists or isfile, d.read or readfile, d.write or writefile
	local prefix = d.prefix or ("RoGhoul/config/" .. tostring(userId))
	local api = { revision = 0, slot = 0, message = "Готово" }
	local booleans = { farm = true, npcFarm = true, autoClick = true, autoArata = true, autoMask = true, autoAlly = true, autoTrainer = true, godMode = true, bossPriorityEnabled = true }
	local ranges = { distance = {2,40}, moveSpeed = {20,400}, clickInterval = {0.02,1}, skillInterval = {0.15,3}, weaponStage = {1,9}, absorbNPC = {0,1} }
	local function finite(v) return type(v) == "number" and v == v and math.abs(v) < math.huge end
	local function name(v) return type(v) == "string" and #v > 0 and #v <= 160 end
	function api:Validate(data)
		if type(data) ~= "table" or data.version ~= 1 or data.userId ~= userId or not finite(data.revision)
			or data.revision < 1 or data.revision > 1000000000 or data.revision % 1 ~= 0 or type(data.options) ~= "table" then return nil end
		local out = { version = 1, userId = userId, revision = data.revision, options = {}, ui = {} }
		for k, v in pairs(data.options) do
			if booleans[k] then if type(v) ~= "boolean" then return nil end; out.options[k] = v
			elseif ranges[k] then
				local r = ranges[k]; if not finite(v) or v < r[1] or v > r[2] or ((k == "weaponStage" or k == "absorbNPC") and v % 1 ~= 0) then return nil end
				out.options[k] = v
			elseif k == "farmMethod" then if v ~= "Above" and v ~= "Behind" and v ~= "Down" then return nil end; out.options[k] = v
			elseif k == "cMode" then if v ~= "Use" and v ~= "Toggle" then return nil end; out.options[k] = v
			elseif k == "selectedTrainer" then if not name(v) then return nil end; out.options[k] = v
			elseif k == "skills" then
				if type(v) ~= "table" then return nil end; out.options[k] = {}
				for _, key in ipairs({"E","R","F","C"}) do if v[key] ~= nil and type(v[key]) ~= "boolean" then return nil end; out.options[k][key] = v[key] == true end
			elseif k == "selectedBosses" or k == "selectedNPCs" or k == "bossPriority" then
				if type(v) ~= "table" then return nil end
				local clean, seen, count = {}, {}, 0
				for key, val in pairs(v) do
					count += 1; if count > 256 then return nil end
					if k == "bossPriority" then
						if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > #v or not name(val) or seen[val] then return nil end
						clean[key], seen[val] = val, true
					else if not name(key) or type(val) ~= "boolean" then return nil end; if val then clean[key] = true end end
				end
				if k == "bossPriority" and count ~= #v then return nil end
				out.options[k] = clean
			end -- Unknown fields are ignored, never passed to the controller.
		end
		local u = data.ui or {}; if type(u) ~= "table" then return nil end
		if u.language ~= nil and u.language ~= "ru" and u.language ~= "en" then return nil end
		if u.antiAFK ~= nil and type(u.antiAFK) ~= "boolean" then return nil end
		if u.menu ~= nil and type(u.menu) ~= "boolean" then return nil end
		if u.tab ~= nil and (not finite(u.tab) or u.tab < 1 or u.tab > 6 or u.tab % 1 ~= 0) then return nil end
		out.ui.language, out.ui.antiAFK, out.ui.menu, out.ui.tab = u.language or "ru", u.antiAFK ~= false, u.menu ~= false, u.tab or 1
		for _, key in ipairs({"position", "size"}) do
			if u[key] ~= nil then
				if type(u[key]) ~= "table" or #u[key] ~= 4 then return nil end
				local a = {}; for i = 1, 4 do if not finite(u[key][i]) or math.abs(u[key][i]) > 10000 then return nil end; a[i] = u[key][i] end
				if key == "size" and (a[1]<0 or a[1]>1 or a[3]<0 or a[3]>1 or a[2]<0 or a[4]<0 or a[1]+a[2]<=0 or a[3]+a[4]<=0) then return nil end
				out.ui[key] = a
			end
		end
		if u.scale ~= nil then if not finite(u.scale) or u.scale < 0.5 or u.scale > 2 then return nil end; out.ui.scale = u.scale end
		return out
	end
	function api:Load()
		local best, bad = nil, false
		if type(exists) ~= "function" or type(read) ~= "function" or type(write) ~= "function" then self.message = "Сохранение недоступно"; return nil end
		for slot = 1, 2 do
			local ok, value = pcall(function()
				local path = prefix .. "." .. slot .. ".json"
				if not exists(path) then return nil end
				local bytes = read(path); assert(#bytes <= 131072, "Config too large")
				return assert(self:Validate(http:JSONDecode(bytes)), "Invalid config")
			end)
			if not ok then bad = true elseif value and (not best or value.revision > best.revision) then best = value; self.slot = slot end
		end
		if best then self.revision = best.revision end
		self.message = bad and (best and "Восстановлен резервный конфиг" or "Конфиг повреждён: используются настройки по умолчанию") or best and "Конфиг загружен" or "Настройки сохраняются автоматически"
		return best
	end
	function api:Apply(controller, data)
		-- This gate is independent of the diagnostic suspension and of saved toggle states.
		controller:SetStartupCombatHeld(true)
		if data then for key, val in pairs(data.options) do if key ~= "farm" and key ~= "npcFarm" and key ~= "autoTrainer" then controller:SetOption(key, val) end end end
		controller:SetOption("farm", false); controller:SetOption("npcFarm", false); controller:SetOption("autoTrainer", false)
	end
	function api:Save(options, ui)
		local ok, err = pcall(function()
			assert(type(write) == "function" and type(read) == "function", "Filesystem unavailable")
			local data = assert(self:Validate({version = 1, userId = userId, revision = self.revision + 1, options = options, ui = ui}), "Invalid preferences")
			local slot = self.slot == 1 and 2 or 1
			local bytes = http:JSONEncode(data); local path = prefix .. "." .. slot .. ".json"
			write(path, bytes)
			assert(read(path) == bytes and self:Validate(http:JSONDecode(bytes)), "Config verification failed")
			self.slot, self.revision = slot, data.revision
		end)
		self.message = ok and "Настройки сохранены" or "Ошибка сохранения: " .. tostring(err)
		if not ok then warn("Ro-Ghoul config: " .. tostring(err)) end
		return ok
	end
	return api
end
