session = [=[--!nonstrict
-- Actual replicated balances, not attempts, kills or locally written game values.
return function(scope, inherited, injected)
	local d = injected or {}
	local player = d.player or game:GetService("Players").LocalPlayer
	local jobId = d.jobId or game.JobId
	local dataModel = d.dataModel or game
	local ledger = inherited and inherited.jobId == jobId and inherited.userId == player.UserId and inherited.dataModel == dataModel and inherited
		or { jobId = jobId, userId = player.UserId, dataModel = dataModel, gains = { Yen = 0, RC = 0, Reputation = 0, Hearts = 0 } }
	local paths = { Yen = {"Stats","Yen"}, RC = {"Stats","RC"}, Reputation = {"Stats","Reputation"}, Hearts = {"Inventory","Hearts"} }
	local sources, last, links = {}, {}, {}
	local api = { Ledger = ledger }
	local function numeric(v)
		local n = tonumber(v); return n and n == n and n >= 0 and n < math.huge and n or nil
	end
	local function resolve(path)
		local folder = player:FindFirstChild("PlayerFolder")
		for _, part in ipairs(path) do folder = folder and folder:FindFirstChild(part) end
		return folder and (folder:IsA("StringValue") or folder:IsA("NumberValue") or folder:IsA("IntValue")) and folder or nil
	end
	local function sample(key, source)
		if sources[key] ~= source or resolve(paths[key]) ~= source then return end
		local n = numeric(source.Value)
		if n and last[key] and n > last[key] then ledger.gains[key] += n - last[key] end
		last[key] = n -- Spending establishes a new baseline; it does not subtract earnings.
	end
	function api:Refresh()
		for key, path in pairs(paths) do
			local source = resolve(path)
			if source ~= sources[key] then
				if links[key] then links[key]:Disconnect(); links[key] = nil end
				sources[key], last[key] = source, source and numeric(source.Value) or nil
				if source then links[key] = source:GetPropertyChangedSignal("Value"):Connect(function() if scope.alive() then sample(key, source) end end) end
			end
		end
	end
	function api:Reset()
		self:Refresh()
		for key in pairs(paths) do ledger.gains[key] = 0; last[key] = sources[key] and numeric(sources[key].Value) or nil end
	end
	function api:GetStatus()
		local out = {}; for key in pairs(paths) do out[key] = { gained = ledger.gains[key], available = sources[key] ~= nil and last[key] ~= nil } end
		return out
	end
	scope.onCleanup(function() for _, link in pairs(links) do link:Disconnect() end end)
	api:Refresh()
	return api
end
]=],
antiAFK = [=[--!nonstrict
-- One scoped Idled listener. No M1, movement loop, game hooks or disabled listeners.
return function(scope, injected)
	local d = injected or {}
	local player = d.player or game:GetService("Players").LocalPlayer
	local clock = d.clock or os.clock
	local pulse = d.pulse or function()
		local user = game:GetService("VirtualUser")
		local camera = workspace.CurrentCamera
		assert(camera, "Camera unavailable")
		user:CaptureController()
		local ok, err = pcall(function() user:Button2Down(Vector2.zero, camera.CFrame) end)
		-- Always release immediately, including the failed-Down path; never leave RMB held.
		local released, releaseError = pcall(function() user:Button2Up(Vector2.zero, camera.CFrame) end)
		assert(ok and released, tostring(err or releaseError))
	end
	local api = { enabled = true, pulses = 0, lastError = nil }
	local nextAt = 0
	function api:SetEnabled(value) self.enabled = value == true end
	function api:HandleIdle()
		if not api.enabled or not scope.alive() or clock() < nextAt then return end
		nextAt = clock() + 30
		local ok, err = pcall(pulse)
		if ok then api.pulses += 1; api.lastError = nil
		else api.lastError = tostring(err); warn("Ro-Ghoul Anti-AFK: " .. tostring(err)) end
	end
	scope.connect(player.Idled, function() api:HandleIdle() end)
	return api
end
]=],
