		["включено"]="enabled", ["выключено"]="disabled", ["Смерти NPC: "]="NPC deaths: ", ["Попытки поглощения: "]="Absorption attempts: ", ["босс"]="boss", ["нет"]="none", [" с"]=" s",
		["Готово"]="Ready", ["Отменено"]="Cancelled", ["Подключение…"]="Connecting…", ["Переход не выполнен: "]="Transfer failed: ", ["Переход не подтвердился. Попробуйте снова."]="Transfer not confirmed. Try again.",
		["Поиск свободного сервера…"]="Finding a free server…", ["Поиск превысил 15 с. Попробуйте снова."]="Search exceeded 15 s. Try again.",
		["Список серверов недоступен (HTTP "]="Server list unavailable (HTTP ", ["ошибка запроса"]="request error", ["Неверный ответ списка серверов."]="Invalid server list response.",
		["Другой неполный сервер не найден. Попробуйте позже."]="No other non-full server found. Try later.", ["Roblox отклонил переход. Попробуйте снова."]="Roblox rejected the transfer. Try again.", ["Переход на сервер…"]="Leaving for server…",
		["Сохранение недоступно"]="Saving unavailable", ["Восстановлен резервный конфиг"]="Backup config restored", ["Конфиг повреждён: используются настройки по умолчанию"]="Config corrupted: using defaults",
		["Конфиг загружен"]="Config loaded", ["Настройки сохраняются автоматически"]="Preferences are saved automatically", ["Настройки сохранены"]="Preferences saved", ["Ошибка сохранения: "]="Save error: ",
		["Поиск..."]="Search...", ["Подтвердить"]="Confirm", ["Отмена"]="Cancel",
		["Выйти из меню? Несохранённые настройки могут быть потеряны."]="Are you sure you want to exit the menu? You will lose any unsaved configurations.",
		["Меню развёрнуто. Нажмите "]="Maximized the menu. Use ", ["Меню свёрнуто. Нажмите "]="Minimized the menu. Use ", [" для переключения."]=" to toggle it.",
	}
	local keys = {}; for key in pairs(phrases) do table.insert(keys, key) end
	table.sort(keys, function(a,b) return #a > #b end)
	local library = { ["Search..."]="Поиск...", Confirm="Подтвердить", Cancel="Отмена",
		["Are you sure you want to exit the menu? You will lose any unsaved configurations."]="Выйти из меню? Несохранённые настройки могут быть потеряны." }
	local api = { language = initial == "en" and "en" or "ru" }
	function api:Translate(raw)
		if self.language ~= "en" then return raw end
		for _, key in ipairs(keys) do raw = raw:gsub(key:gsub("(%W)", "%%%1"), function() return phrases[key] end) end
		return raw
	end
	local function canonical(raw)
		if library[raw] then return library[raw] end
		local action, key = raw:match("^(%a+) the menu%. Use (.+) to toggle it%.$")
		if action == "Maximized" or action == "Minimized" then return (action == "Maximized" and "Меню развёрнуто. Нажмите " or "Меню свёрнуто. Нажмите ") .. key .. " для переключения." end
		return raw
	end
