bossStatus = [=[--!nonstrict
-- Fresh spawn evidence, independent of discovery history, selections, locks and safe zones.
return function(injected)
	local d = injected or {}
	local world = d.world or workspace
	local players = d.players or game:GetService("Players")
	local slots = { FL = true, FR = true, BL = true, BR = true }
	local function alive(model, statue)
		if not model:IsA("Model") or model:FindFirstChild("AC") or players:GetPlayerFromCharacter(model) then return false end
		local hum = model:FindFirstChild("Humanoid") or statue and model:FindFirstChild("Statue")
		return hum and hum:IsA("Humanoid") and hum.Health == hum.Health and hum.Health > 0 and hum.Health < math.huge
			and hum:GetState() ~= Enum.HumanoidStateType.Dead or false
	end
	return function(names)
		local out = {}; for _, name in ipairs(names) do out[name] = false end
		local spawns = world:FindFirstChild("NPCSpawns")
		if spawns then for _, spawn in ipairs(spawns:GetChildren()) do
			if spawn:IsA("BasePart") and (spawn.Name == "BossSpawns" or spawn.Name == "GyakusatsuSpawn") then
				for _, model in ipairs(spawn:GetChildren()) do
					if spawn.Name == "BossSpawns" and alive(model, false) then out[model.Name] = true
					elseif spawn.Name == "GyakusatsuSpawn" and (model.Name == "Gyakusatsu" or slots[model.Name]) and alive(model, true) then out.Gyakusatsu = true end
				end
			end
		end end
		local head = world:FindFirstChild("Gyakusatsu")
		if head and alive(head, false) then out.Gyakusatsu = true end -- Never count the infinite-health display rig.
		return out
	end
end
]=],
